import {
	ASYNC_BOUNDARY_ARM_MAX,
	ASYNC_BOUNDARY_ARM_MIN,
	ASYNC_BOUNDARY_ARM_PENDING,
} from './protocol-constants.ts';

export const ASYNC_BOUNDARY_ARM = {
	try: ASYNC_BOUNDARY_ARM_MIN,
	pending: ASYNC_BOUNDARY_ARM_PENDING,
	catch: ASYNC_BOUNDARY_ARM_MAX,
} as const;

export * from './payload-scripts.ts';
export * from './protocol.ts';
export * from './protocol-state.ts';
export * from './protocol-validation-storage.ts';
export * from './resume-record-delta.ts';
export * from './storage-slot.ts';
export * from './value.ts';

import type { ProtocolStatePayload, ProtocolViewPayload } from './protocol.ts';

export type RenderPayloadScriptsInput = {
	readonly state: ProtocolStatePayload;
	readonly view: ProtocolViewPayload;
};

export type RenderedPayloadScripts = {
	readonly state: ProtocolStatePayload;
	readonly view: ProtocolViewPayload;
	readonly stateScript: string;
	readonly viewScript: string;
};

export function renderPayloadScripts(input: RenderPayloadScriptsInput): RenderedPayloadScripts {
	return {
		state: input.state,
		view: input.view,
		stateScript: renderDataScript('markless/state', input.state),
		viewScript: renderDataScript('markless/view', input.view),
	};
}

function renderDataScript(type: 'markless/state' | 'markless/view', payload: unknown): string {
	return `<script type="${type}">${escapeScriptJson(JSON.stringify(payload))}</script>`;
}

function escapeScriptJson(value: string): string {
	return value.replace(/</g, '\\u003C');
}

import {
	decodePayloadScriptsWithVersion,
	payloadInvalidError,
	type DecodedPayloadScripts,
	type EncodedPayloadScripts,
} from './protocol-client.ts';
import { validateStorageRecords } from './storage-record-client.ts';

export {
	payloadInvalidError,
	payloadScriptSelector,
	RuntimePayloadError,
	type DecodedPayloadScripts,
	type EncodedPayloadScripts,
	type RuntimePayloadDiagnostic,
	type RuntimePayloadErrorCode,
	type RuntimePayloadType,
} from './protocol-client.ts';

export function decodePayloadScripts(input: EncodedPayloadScripts): DecodedPayloadScripts {
	const decoded = decodePayloadScriptsWithVersion(input, true);
	validateStorageRecords(decoded.state, payloadInvalidError);
	return decoded;
}

import {
	ASYNC_BOUNDARY_ARM_MAX,
	ASYNC_BOUNDARY_ARM_MIN,
	ASYNC_PROTOCOL_VERSION,
	STORAGE_PROTOCOL_VERSION,
} from './protocol-constants.ts';
import {
	PROTOCOL_EVENT_ACTION_KIND,
	type ProtocolEventActionKind,
	type ProtocolStatePayload,
	type ProtocolViewPayload,
} from './protocol.ts';
export type EncodedPayloadScripts = { readonly stateScript: string; readonly viewScript: string };
export type DecodedPayloadScripts = {
	readonly state: ProtocolStatePayload;
	readonly view: ProtocolViewPayload;
};
export type RuntimePayloadType = 'markless/state' | 'markless/view';
export type RuntimePayloadErrorCode =
	| 'MARKLESS_PAYLOAD_INVALID'
	| 'MARKLESS_PROTOCOL_VERSION_MISMATCH';
export type RuntimePayloadDiagnostic = {
	readonly code: RuntimePayloadErrorCode;
	readonly severity: 'error';
	readonly phase: 'payload';
	readonly title: string;
	readonly message: string;
	readonly why: string;
	readonly payloadType: RuntimePayloadType;
	readonly payloadScript: string;
	readonly expectedVersion?: number;
	readonly actualVersion?: unknown;
	readonly suggestions: ReadonlyArray<{ readonly message: string }>;
	readonly docsUrl: string;
};
export class RuntimePayloadError extends Error implements RuntimePayloadDiagnostic {
	declare readonly code: RuntimePayloadErrorCode;
	declare readonly severity: 'error';
	declare readonly phase: 'payload';
	declare readonly title: string;
	declare readonly why: string;
	declare readonly payloadType: RuntimePayloadType;
	declare readonly payloadScript: string;
	declare readonly expectedVersion?: number;
	declare readonly actualVersion?: unknown;
	declare readonly suggestions: ReadonlyArray<{ readonly message: string }>;
	declare readonly docsUrl: string;
	constructor(diagnostic: RuntimePayloadDiagnostic) {
		super(diagnostic.message);
		Object.assign(this, { expectedVersion: undefined, actualVersion: undefined }, diagnostic, {
			name: 'RuntimePayloadError',
		});
	}
}
export function decodePayloadScripts(input: EncodedPayloadScripts): DecodedPayloadScripts {
	return decodePayloadScriptsWithVersion(input, false);
}

export function decodePayloadScriptsWithVersion(
	input: EncodedPayloadScripts,
	allowStorage: boolean,
): DecodedPayloadScripts {
	const state = parse(input.stateScript, 'markless/state') as ProtocolStatePayload;
	const view = parse(input.viewScript, 'markless/view') as ProtocolViewPayload;
	baseState(state);
	baseView(view);
	version(state.version, 'markless/state', allowStorage);
	version(view.version, 'markless/view');
	return { state, view };
}
function parse(script: string, type: RuntimePayloadType): unknown {
	const prefix = `<script type="${type}">`;
	if (!script.startsWith(prefix) || !script.endsWith('</script>')) {
		throw payloadInvalidError(type, `Expected ${type} payload script.`);
	}
	try {
		return JSON.parse(script.slice(prefix.length, -9));
	} catch {
		throw payloadInvalidError(type, `Invalid ${type} payload JSON.`);
	}
}
function baseState(value: unknown): asserts value is ProtocolStatePayload {
	const payload = root(value, 'markless/state');
	const cells = arr(payload, 'cells', 'markless/state');
	arr(payload, 'computed', 'markless/state');
	for (const [index, cell] of cells.entries()) {
		const context = `markless/state cell[${index}]`;
		const record = obj(cell, context);
		str(record, 'graphNodeId', context);
		str(record, 'name', context);
		if ('value' in record) serialized(record.value, `${context}.value`);
	}
}
function baseView(value: unknown): asserts value is ProtocolViewPayload {
	const payload = root(value, 'markless/view');
	if ('asyncRunners' in payload) {
		const runners = obj(payload.asyncRunners, 'markless/view asyncRunners');
		for (const [graphNodeId, symbolId] of Object.entries(runners)) {
			if (typeof symbolId !== 'string')
				invalid(`markless/view asyncRunners.${graphNodeId}`, 'expected string.');
		}
	}
	const [locators, events, , , , asyncBoundaries] = (
		[
			'locators',
			'events',
			'domUpdates',
			'behaviors',
			'elementHandles',
			'asyncBoundaries',
		] as const
	).map((key) => arr(payload, key, 'markless/view'));
	for (const [index, locator] of locators.entries()) {
		const context = `markless/view locator[${index}]`;
		const record = obj(locator, context);
		str(record, 'hostNodeId', context);
		str(record, 'tagName', context);
		if (record.strategy !== 'dom-order') invalid(context, 'expected strategy "dom-order".');
		if (!Number.isInteger(record.index) || Number(record.index) < 0)
			invalid(context, 'expected index non-negative integer.');
	}
	for (const [index, event] of events.entries()) {
		const context = `markless/view event[${index}]`;
		const record = obj(event, context);
		str(record, 'hostNodeId', context);
		str(record, 'eventName', context);
		if (!Array.isArray(record.symbolIds)) invalid(context, 'expected symbolIds array.');
		eventAction(record.action, `${context}.action`);
	}
	if (asyncBoundaries.length > 0)
		for (const [index, boundary] of asyncBoundaries.entries()) {
			const context = `markless/view asyncBoundary[${index}]`;
			const record = obj(boundary, context);
			if (record.runnerGraphNodeId !== null && typeof record.runnerGraphNodeId !== 'string')
				invalid(context, 'expected runnerGraphNodeId string or null.');
			if (
				typeof record.initiallyServedArm !== 'number' ||
				!Number.isInteger(record.initiallyServedArm) ||
				record.initiallyServedArm < ASYNC_BOUNDARY_ARM_MIN ||
				record.initiallyServedArm > ASYNC_BOUNDARY_ARM_MAX
			)
				invalid(
					context,
					'expected initiallyServedArm to name a protocol async boundary arm.',
				);
		}
}

const EVENT_ACTION_VALIDATORS = {
	[PROTOCOL_EVENT_ACTION_KIND.event]: () => {},
	[PROTOCOL_EVENT_ACTION_KIND.externalDelegate]: (
		action: Record<string, unknown>,
		context: string,
	) => str(action, 'owner', context),
} satisfies Record<
	ProtocolEventActionKind,
	(action: Record<string, unknown>, context: string) => void
>;

function eventAction(value: unknown, context: string): void {
	if (value === undefined) return;
	const action = obj(value, context);
	str(action, 'kind', context);
	const validate = EVENT_ACTION_VALIDATORS[action.kind as ProtocolEventActionKind];
	if (!validate) invalid(context, 'unknown event action kind.');
	validate(action, context);
}
function root(value: unknown, type: RuntimePayloadType): Record<string, unknown> {
	const record = obj(value, type);
	if (!('version' in record))
		throw payloadInvalidError(type, `Invalid ${type} payload: expected version.`);
	return record;
}
function obj(value: unknown, context: string): Record<string, unknown> {
	if (typeof value === 'object' && value !== null && !Array.isArray(value))
		// TS narrows `unknown` only to `object` here; the index signature is the JS truth.
		return value as Record<string, unknown>;
	throw invalid(context, 'expected object.');
}
function arr(record: Record<string, unknown>, key: string, type: RuntimePayloadType): unknown[] {
	if (Array.isArray(record[key])) return record[key];
	throw payloadInvalidError(type, `Invalid ${type} payload: expected ${key} array.`);
}
function str(record: Record<string, unknown>, key: string, context: string): void {
	if (typeof record[key] !== 'string') invalid(context, `expected ${key} string.`);
}
function serialized(value: unknown, context: string): void {
	const record = obj(value, context);
	if (record.version !== 1) invalid(context, 'expected version 1.');
	if (!('root' in record)) invalid(context, 'expected root.');
	if (!Array.isArray(record.records)) invalid(context, 'expected records array.');
}
function version(actualVersion: unknown, type: RuntimePayloadType, allowStorage = false): void {
	if (
		actualVersion === ASYNC_PROTOCOL_VERSION ||
		(allowStorage && type === 'markless/state' && actualVersion === STORAGE_PROTOCOL_VERSION)
	)
		return;
	throw new RuntimePayloadError({
		code: 'MARKLESS_PROTOCOL_VERSION_MISMATCH',
		severity: 'error',
		phase: 'payload',
		title: 'Unsupported resumability protocol version',
		message: `Unsupported ${type} protocol version ${String(actualVersion)}.`,
		why: `The ${type} payload must use a supported protocol version.`,
		payloadType: type,
		payloadScript: payloadScriptSelector(type),
		expectedVersion: ASYNC_PROTOCOL_VERSION,
		actualVersion,
		suggestions: [{ message: `Serve a ${type} payload generated by this runtime.` }],
		docsUrl: 'https://markless.dev/errors/MARKLESS_PROTOCOL_VERSION_MISMATCH',
	});
}
function invalid(context: string, reason: string): never {
	throw payloadInvalidError(
		context.startsWith('markless/view') ? 'markless/view' : 'markless/state',
		`Invalid ${context}: ${reason}`,
	);
}
export function payloadInvalidError(
	type: RuntimePayloadType,
	message: string,
	why = `${type} did not match the required resume payload shape.`,
	suggestions: ReadonlyArray<{ readonly message: string }> = [
		{ message: `Emit a valid ${type} payload script.` },
	],
): RuntimePayloadError {
	return new RuntimePayloadError({
		code: 'MARKLESS_PAYLOAD_INVALID',
		severity: 'error',
		phase: 'payload',
		title: 'Invalid resumability payload',
		message,
		why,
		payloadType: type,
		payloadScript: payloadScriptSelector(type),
		suggestions,
		docsUrl: 'https://markless.dev/errors/MARKLESS_PAYLOAD_INVALID',
	});
}
export function payloadScriptSelector(type: RuntimePayloadType): string {
	return `script[type="${type}"]`;
}

export const ASYNC_PROTOCOL_VERSION = 1;
export const STORAGE_PROTOCOL_VERSION = 2;

export const ASYNC_BOUNDARY_ARM_MIN = 0;
export const ASYNC_BOUNDARY_ARM_PENDING = 1;
export const ASYNC_BOUNDARY_ARM_MAX = 2;

import {
	ASYNC_PROTOCOL_VERSION,
	STORAGE_PROTOCOL_VERSION,
	type ProtocolStatePayload,
} from './protocol.ts';
import {
	serializeGraphValue,
	type SerializedGraphPayload,
	type SerializationDiagnostic,
} from './value.ts';

export type ProtocolAsyncComputedSnapshotInput =
	| {
			readonly status: 'idle';
			readonly version: 0;
	  }
	| {
			readonly status: 'pending';
			readonly version: number;
			readonly key: unknown;
	  }
	| {
			readonly status: 'fulfilled';
			readonly version: number;
			readonly key: unknown;
			readonly value: unknown;
	  }
	| {
			readonly status: 'rejected';
			readonly version: number;
			readonly key: unknown;
			readonly error: unknown;
	  };

export type ProtocolStatePayloadInput = {
	readonly cells: ReadonlyArray<{
		readonly graphNodeId: string;
		readonly name: string;
		readonly valueKind: 'scalar' | 'object' | 'array' | 'unknown';
		readonly value: unknown;
	}>;
	readonly computed?: ReadonlyArray<
		Omit<ProtocolStatePayload['computed'][number], 'snapshot'> & {
			readonly snapshot?: ProtocolAsyncComputedSnapshotInput;
		}
	>;
	readonly sharedDefinitions?: ProtocolStatePayload['sharedDefinitions'];
	readonly storage?: ProtocolStatePayload['storage'];
};

export type ProtocolStateSerializationDiagnostic = SerializationDiagnostic & {
	readonly graphNodeId: string;
	readonly cellName: string;
};

export class ProtocolStateSerializationError
	extends Error
	implements ProtocolStateSerializationDiagnostic
{
	readonly code: SerializationDiagnostic['code'];
	readonly severity: SerializationDiagnostic['severity'];
	readonly phase: SerializationDiagnostic['phase'];
	readonly title: SerializationDiagnostic['title'];
	readonly path: SerializationDiagnostic['path'];
	readonly statePath: SerializationDiagnostic['statePath'];
	readonly valueKind: SerializationDiagnostic['valueKind'];
	readonly why: SerializationDiagnostic['why'];
	readonly suggestions: SerializationDiagnostic['suggestions'];
	readonly docsUrl: SerializationDiagnostic['docsUrl'];
	readonly graphNodeId: string;
	readonly cellName: string;

	constructor(diagnostic: ProtocolStateSerializationDiagnostic) {
		super(diagnostic.message);
		this.name = 'ProtocolStateSerializationError';
		this.code = diagnostic.code;
		this.severity = diagnostic.severity;
		this.phase = diagnostic.phase;
		this.title = diagnostic.title;
		this.path = diagnostic.path;
		this.statePath = diagnostic.statePath;
		this.valueKind = diagnostic.valueKind;
		this.why = diagnostic.why;
		this.suggestions = diagnostic.suggestions;
		this.docsUrl = diagnostic.docsUrl;
		this.graphNodeId = diagnostic.graphNodeId;
		this.cellName = diagnostic.cellName;
	}
}

export function createProtocolStatePayload(input: ProtocolStatePayloadInput): ProtocolStatePayload {
	const storage = input.storage ?? [];
	return {
		version: storage.length > 0 ? STORAGE_PROTOCOL_VERSION : ASYNC_PROTOCOL_VERSION,
		cells: input.cells.map((cell) => {
			const result = serializeGraphValue(cell.value);
			if (!result.ok) {
				throw protocolStateSerializationError(cell, result.diagnostics[0]);
			}

			return {
				graphNodeId: cell.graphNodeId,
				name: cell.name,
				valueKind: cell.valueKind,
				value: result.payload,
			};
		}),
		computed: (input.computed ?? []).map(serializeComputedSnapshot),
		sharedDefinitions: input.sharedDefinitions,
		...(storage.length > 0 ? { storage } : {}),
	};
}

// Live-value cells (directValue, need 14) hold values that never crossed
// HTML. Before a payload is SERVED, those values must become envelope-encoded
// `value` fields — payload decoding rejects a leaked directValue. Cells that
// are already encoded pass through untouched.
export function serializeRuntimeStateCells(
	cells: ProtocolStatePayload['cells'],
): ProtocolStatePayload['cells'] {
	return cells.map((cell) => {
		if (cell.directValue === undefined) return cell;
		const durable = {
			graphNodeId: cell.graphNodeId,
			name: cell.name ?? '',
			valueKind: cell.valueKind ?? ('unknown' as const),
			value: cell.directValue,
		};
		const result = serializeGraphValue(cell.directValue);
		if (!result.ok) {
			throw protocolStateSerializationError(durable, result.diagnostics[0]);
		}
		return { ...durable, value: result.payload };
	});
}

// Render paths attach raw snapshots at runtime (SSR awaits async work, then
// records the settled result); the served payload needs envelope-encoded
// key/value fields, so hosts re-encode through this before emitting scripts.
export function serializeRuntimeAsyncSnapshots(
	computed: ProtocolStatePayload['computed'],
): ProtocolStatePayload['computed'] {
	return computed.map((record) =>
		serializeComputedSnapshot(record as never),
	) as ProtocolStatePayload['computed'];
}

function serializeComputedSnapshot(
	computed: NonNullable<ProtocolStatePayloadInput['computed']>[number],
): ProtocolStatePayload['computed'][number] {
	if (!computed.snapshot) return computed;
	if (computed.snapshot.status === 'idle')
		return computed as ProtocolStatePayload['computed'][number];

	const key = serializeProtocolStateField(computed, 'key', computed.snapshot.key);
	if (computed.snapshot.status === 'pending') {
		return {
			...computed,
			snapshot: {
				status: computed.snapshot.status,
				version: computed.snapshot.version,
				key,
			},
		};
	}

	if (computed.snapshot.status === 'fulfilled') {
		return {
			...computed,
			snapshot: {
				status: computed.snapshot.status,
				version: computed.snapshot.version,
				key,
				value: serializeProtocolStateField(computed, 'value', computed.snapshot.value),
			},
		};
	}

	return {
		...computed,
		snapshot: {
			status: computed.snapshot.status,
			version: computed.snapshot.version,
			key,
			error: serializeProtocolStateField(
				computed,
				'error',
				durableSnapshotError(computed.snapshot.error),
			),
		},
	};
}

// Rejected async snapshots routinely hold live Error instances (a failed fetch
// rejects with TypeError). Refusing to serialize them would fail the WHOLE page
// render over an error the page's @catch arm already handled — keep the durable
// facts (name/message) and drop the live object.
function durableSnapshotError(error: unknown): unknown {
	if (error instanceof Error) {
		return { $type: 'error', name: error.name, message: error.message };
	}
	return error;
}

function serializeProtocolStateField(
	computed: NonNullable<ProtocolStatePayloadInput['computed']>[number],
	field: string,
	value: unknown,
): SerializedGraphPayload {
	const result = serializeGraphValue(value);
	if (!result.ok) {
		throw protocolStateSerializationError(
			{
				graphNodeId: computed.graphNodeId,
				name: `${computed.name}.snapshot.${field}`,
				valueKind: 'unknown',
				value,
			},
			result.diagnostics[0],
		);
	}

	return result.payload;
}

function protocolStateSerializationError(
	cell: ProtocolStatePayloadInput['cells'][number],
	diagnostic: SerializationDiagnostic | undefined,
): ProtocolStateSerializationError {
	const cellPrefix = cell.name === '' ? cell.graphNodeId : cell.name;
	const base = diagnostic ?? {
		code: 'MARKLESS_SERIALIZE_UNSUPPORTED_VALUE' as const,
		severity: 'error' as const,
		phase: 'serialization' as const,
		title: 'Cannot serialize graph state value' as const,
		path: [],
		statePath: cellPrefix,
		valueKind: 'unknown',
		message: `Cannot serialize value at ${cellPrefix} because unknown values are not durable graph state.`,
		why: 'Serialization is for durable graph state. Functions and host/runtime resources cannot be restored during resume.',
		suggestions: [
			{
				message:
					'Move runtime resources into attach={...}, make the value serializable state, or derive it with computed().',
			},
		],
		docsUrl: 'https://markless.dev/errors/MARKLESS_SERIALIZE_UNSUPPORTED_VALUE',
	};
	const statePath = base.statePath === '<root>' ? cellPrefix : `${cellPrefix}.${base.statePath}`;

	return new ProtocolStateSerializationError({
		...base,
		graphNodeId: cell.graphNodeId,
		cellName: cell.name,
		statePath,
		message: `Cannot serialize value at ${statePath} because ${base.valueKind} values are not durable graph state.`,
	});
}

import {
	decodePayloadScriptsWithVersion,
	invalidPayloadShapeError,
	type DecodedPayloadScripts,
	type EncodedPayloadScripts,
} from './protocol-validation.ts';
import { STORAGE_PROTOCOL_VERSION } from './protocol-constants.ts';
import { isValidStorageKey } from './storage-key.ts';

export * from './protocol-validation.ts';

export function decodePayloadScripts(input: EncodedPayloadScripts): DecodedPayloadScripts {
	const decoded = decodePayloadScriptsWithVersion(input, true);
	if (decoded.state.version !== STORAGE_PROTOCOL_VERSION) return decoded;
	const cellIds = new Set(decoded.state.cells.map((cell) => cell.graphNodeId));
	const storage = (decoded.state as unknown as Record<string, unknown>).storage;
	if (!Array.isArray(storage))
		throw invalidPayloadShapeError(
			'markless/state',
			'Invalid markless/state payload: expected storage array.',
		);
	for (const [index, entry] of storage.entries()) {
		const context = `markless/state storage[${index}]`;
		if (typeof entry !== 'object' || entry === null || Array.isArray(entry))
			throw invalidPayloadShapeError(
				'markless/state',
				`Invalid ${context}: expected object.`,
			);
		const record = entry as Record<string, unknown>;
		if (typeof record.graphNodeId !== 'string')
			throw invalidPayloadShapeError(
				'markless/state',
				`Invalid ${context}: expected graphNodeId string.`,
			);
		if (typeof record.key !== 'string')
			throw invalidPayloadShapeError(
				'markless/state',
				`Invalid ${context}: expected key string.`,
			);
		if (!cellIds.has(record.graphNodeId))
			throw invalidPayloadShapeError(
				'markless/state',
				`Invalid ${context}: graphNodeId must match a state cell.`,
			);
		if (!isValidStorageKey(record.key))
			throw invalidPayloadShapeError(
				'markless/state',
				`Invalid ${context}: key must be a verbatim key or a derived markless:<identifier>.`,
			);
	}
	return decoded;
}

import {
	ASYNC_BOUNDARY_ARM,
	ASYNC_PROTOCOL_VERSION,
	PROTOCOL_EVENT_ACTION_KIND,
	STORAGE_PROTOCOL_VERSION,
	type ProtocolEventActionKind,
	type ProtocolStatePayload,
	type ProtocolViewPayload,
} from './protocol.ts';

export type EncodedPayloadScripts = {
	readonly stateScript: string;
	readonly viewScript: string;
};

export type DecodedPayloadScripts = {
	readonly state: ProtocolStatePayload;
	readonly view: ProtocolViewPayload;
};

export type RuntimePayloadType = 'markless/state' | 'markless/view';

export type RuntimePayloadErrorCode =
	| 'MARKLESS_PAYLOAD_INVALID'
	| 'MARKLESS_PROTOCOL_VERSION_MISMATCH';

export type RuntimePayloadDiagnostic = {
	readonly code: RuntimePayloadErrorCode;
	readonly severity: 'error';
	readonly phase: 'payload';
	readonly title: string;
	readonly message: string;
	readonly why: string;
	readonly payloadType: RuntimePayloadType;
	readonly payloadScript: string;
	readonly expectedVersion?: number;
	readonly actualVersion?: unknown;
	readonly suggestions: ReadonlyArray<{ readonly message: string }>;
	readonly docsUrl: string;
};

export class RuntimePayloadError extends Error implements RuntimePayloadDiagnostic {
	declare readonly code: RuntimePayloadErrorCode;
	declare readonly severity: 'error';
	declare readonly phase: 'payload';
	declare readonly title: string;
	declare readonly why: string;
	declare readonly payloadType: RuntimePayloadType;
	declare readonly payloadScript: string;
	declare readonly expectedVersion?: number;
	declare readonly actualVersion?: unknown;
	declare readonly suggestions: ReadonlyArray<{ readonly message: string }>;
	declare readonly docsUrl: string;

	constructor(diagnostic: RuntimePayloadDiagnostic) {
		super(diagnostic.message);
		Object.assign(this, { expectedVersion: undefined, actualVersion: undefined }, diagnostic, {
			name: 'RuntimePayloadError',
		});
	}
}

export function decodePayloadScripts(input: EncodedPayloadScripts): DecodedPayloadScripts {
	return decodePayloadScriptsWithVersion(input, false);
}

export function decodePayloadScriptsWithVersion(
	input: EncodedPayloadScripts,
	allowStorage: boolean,
): DecodedPayloadScripts {
	const state = parseDataScript(input.stateScript, 'markless/state') as ProtocolStatePayload;
	const view = parseDataScript(input.viewScript, 'markless/view') as ProtocolViewPayload;

	assertProtocolStatePayload(state);
	assertProtocolViewPayload(view);
	assertProtocolVersion(state.version, 'markless/state', allowStorage);
	assertProtocolVersion(view.version, 'markless/view');

	return { state, view };
}

function parseDataScript(script: string, type: RuntimePayloadType): unknown {
	const prefix = `<script type="${type}">`;
	const suffix = '</script>';

	if (!script.startsWith(prefix) || !script.endsWith(suffix)) {
		throw payloadInvalidError(
			type,
			`Expected ${type} payload script.`,
			`Browser resume expects the ${type} data to arrive in a canonical ${payloadScriptSelector(type)} script wrapper before decoding the resumability protocol.`,
			[
				{
					message: `Emit the ${type} payload with renderPayloadScripts or an equivalent canonical script wrapper.`,
				},
			],
		);
	}

	try {
		return JSON.parse(script.slice(prefix.length, -suffix.length));
	} catch {
		throw payloadInvalidError(
			type,
			`Invalid ${type} payload JSON.`,
			`The ${type} payload script must contain valid JSON before the runtime can validate the resumability protocol fields.`,
			[
				{
					message: `Emit valid JSON inside the ${payloadScriptSelector(type)} script content.`,
				},
			],
		);
	}
}

export function assertProtocolStatePayload(
	payload: unknown,
): asserts payload is ProtocolStatePayload {
	if (!isRecord(payload)) {
		throw invalidPayloadShapeError(
			'markless/state',
			'Invalid markless/state payload: expected object.',
		);
	}
	if (!('version' in payload)) {
		throw invalidPayloadShapeError(
			'markless/state',
			'Invalid markless/state payload: expected version.',
		);
	}
	const cells = requiredPayloadArrayField(payload, 'cells', 'markless/state');

	for (const [index, cell] of cells.entries()) {
		assertProtocolStateCellPayload(cell, `markless/state cell[${index}]`);
	}

	const computedEntries = requiredPayloadArrayField(payload, 'computed', 'markless/state');

	for (const [index, computed] of computedEntries.entries()) {
		const context = `markless/state computed[${index}]`;
		assertRecordShape(computed, context);
		assertStringField(computed, 'graphNodeId', context);
		assertStringField(computed, 'name', context);
		assertBooleanField(computed, 'async', context);
		assertOptionalComputedDependencies(computed, context);
		assertOptionalAsyncComputedSnapshot(computed, context);
	}

	assertOptionalSharedDefinitions(payload);
}

export function assertProtocolStateCellPayload(
	cell: unknown,
	context: string,
): asserts cell is ProtocolStatePayload['cells'][number] {
	assertRecordShape(cell, context);
	assertStringField(cell, 'graphNodeId', context);
	assertStringField(cell, 'name', context);
	assertStateValueKind(cell, context);
	if ('value' in cell) assertSerializedGraphPayload(cell.value, `${context}.value`);
	// directValue is the live-value channel (CSR mounts): it must never be
	// served. A payload script still carrying one is a host bug — hosts must
	// envelope-encode through serializeRuntimeStateCells before emitting.
	if ('directValue' in cell) {
		throw invalidPayloadShapeError(
			contextPayloadType(context),
			`Invalid ${context}: live directValue cells must be serialized before serving.`,
		);
	}
}

export function assertProtocolViewPayload(
	payload: unknown,
): asserts payload is ProtocolViewPayload {
	if (!isRecord(payload)) {
		throw invalidPayloadShapeError(
			'markless/view',
			'Invalid markless/view payload: expected object.',
		);
	}
	if (!('version' in payload)) {
		throw invalidPayloadShapeError(
			'markless/view',
			'Invalid markless/view payload: expected version.',
		);
	}

	const locators = requiredPayloadArrayField(payload, 'locators', 'markless/view');
	const events = requiredPayloadArrayField(payload, 'events', 'markless/view');
	const domUpdates = requiredPayloadArrayField(payload, 'domUpdates', 'markless/view');
	const behaviors = requiredPayloadArrayField(payload, 'behaviors', 'markless/view');
	const elementHandles = requiredPayloadArrayField(payload, 'elementHandles', 'markless/view');
	const asyncBoundaries = requiredPayloadArrayField(payload, 'asyncBoundaries', 'markless/view');
	assertOptionalStringRecord(payload.asyncRunners, 'markless/view asyncRunners');

	for (const [index, locator] of locators.entries()) {
		const context = `markless/view locator[${index}]`;
		assertRecordShape(locator, context);
		assertStringField(locator, 'hostNodeId', context);
		assertLiteralField(locator, 'strategy', 'dom-order', context);
		assertNonNegativeIntegerField(locator, 'index', context);
		assertStringField(locator, 'tagName', context);
	}

	for (const [index, event] of events.entries()) {
		const context = `markless/view event[${index}]`;
		assertRecordShape(event, context);
		assertStringField(event, 'hostNodeId', context);
		assertStringField(event, 'eventName', context);
		assertStringArrayField(event, 'symbolIds', context);
		assertOptionalEventAction(event.action, `${context}.action`);
		if (event.syncPolicy !== undefined) {
			assertSyncPolicy(event.syncPolicy, `${context}.syncPolicy`);
		}
	}

	for (const [index, domUpdate] of domUpdates.entries()) {
		const context = `markless/view domUpdate[${index}]`;
		assertRecordShape(domUpdate, context);
		assertStringField(domUpdate, 'hostNodeId', context);
		assertStringField(domUpdate, 'source', context);
		assertStringField(domUpdate, 'graphNodeId', context);
		assertStringArrayField(domUpdate, 'path', context);
		assertOptionalDomUpdateTarget(domUpdate.target, `${context}.target`);
		assertOptionalStringField(domUpdate, 'symbolId', context);
	}

	for (const [index, behavior] of behaviors.entries()) {
		const context = `markless/view behavior[${index}]`;
		assertRecordShape(behavior, context);
		assertStringField(behavior, 'hostNodeId', context);
		assertStringField(behavior, 'source', context);
		assertStringField(behavior, 'functionSource', context);
		assertStringArrayField(behavior, 'inputSources', context);
		assertOptionalArrayField(behavior, 'inputValues', context);
		assertOptionalBehaviorInputGraphReads(behavior, context);
		assertOptionalStringField(behavior, 'symbolId', context);
	}

	for (const [index, handle] of elementHandles.entries()) {
		const context = `markless/view elementHandle[${index}]`;
		assertRecordShape(handle, context);
		assertStringField(handle, 'hostNodeId', context);
		assertStringField(handle, 'handleId', context);
		assertStringField(handle, 'name', context);
	}

	for (const [index, boundary] of asyncBoundaries.entries()) {
		const context = `markless/view asyncBoundary[${index}]`;
		assertRecordShape(boundary, context);
		assertStringField(boundary, 'id', context);
		assertNullableStringField(boundary, 'runnerGraphNodeId', context);
		assertAsyncBoundaryArm(boundary.initiallyServedArm, context);
		assertCommentAnchor(boundary.startAnchor, `${context}.startAnchor`);
		assertCommentAnchor(boundary.endAnchor, `${context}.endAnchor`);
		assertAsyncBoundaryReads(boundary.asyncReads, context);
	}

	assertOptionalKeyedRepeats(payload);
	assertOptionalBranches(payload);
}

const EVENT_ACTION_VALIDATORS = {
	[PROTOCOL_EVENT_ACTION_KIND.event]: () => {},
	[PROTOCOL_EVENT_ACTION_KIND.externalDelegate]: (
		action: Record<string, unknown>,
		context: string,
	) => assertStringField(action, 'owner', context),
} satisfies Record<
	ProtocolEventActionKind,
	(action: Record<string, unknown>, context: string) => void
>;

function assertOptionalEventAction(value: unknown, context: string): void {
	if (value === undefined) return;
	assertRecordShape(value, context);
	assertStringField(value, 'kind', context);
	const kind = value.kind as ProtocolEventActionKind;
	const validate = EVENT_ACTION_VALIDATORS[kind];
	if (!validate)
		throw invalidPayloadShapeError(
			contextPayloadType(context),
			`Invalid ${context}: unknown event action kind.`,
		);
	validate(value, context);
}

function assertNullableStringField(
	record: Record<string, unknown>,
	field: string,
	context: string,
): void {
	if (record[field] !== null && typeof record[field] !== 'string') {
		throw invalidPayloadShapeError(
			contextPayloadType(context),
			`Invalid ${context}: expected ${field} string or null.`,
		);
	}
}

function assertAsyncBoundaryArm(value: unknown, context: string): void {
	if (!Object.values(ASYNC_BOUNDARY_ARM).includes(value as never)) {
		throw invalidPayloadShapeError(
			contextPayloadType(context),
			`Invalid ${context}: expected initiallyServedArm to name a protocol async boundary arm.`,
		);
	}
}

function assertProtocolVersion(
	version: unknown,
	type: RuntimePayloadType,
	allowStorage = false,
): void {
	if (
		version !== ASYNC_PROTOCOL_VERSION &&
		!(allowStorage && type === 'markless/state' && version === STORAGE_PROTOCOL_VERSION)
	) {
		throw protocolVersionMismatchError(type, version);
	}
}

function isRecord(value: unknown): value is Record<string, unknown> {
	return typeof value === 'object' && value !== null && !Array.isArray(value);
}

function requiredPayloadArrayField(
	record: Record<string, unknown>,
	key: string,
	payloadType: RuntimePayloadType,
): ReadonlyArray<unknown> {
	if (!Object.prototype.hasOwnProperty.call(record, key) || !Array.isArray(record[key])) {
		throw invalidPayloadShapeError(
			payloadType,
			`Invalid ${payloadType} payload: expected ${key} array.`,
		);
	}

	return record[key];
}

function assertRecordShape(
	value: unknown,
	context: string,
): asserts value is Record<string, unknown> {
	if (!isRecord(value)) {
		throw invalidPayloadShapeError(
			contextPayloadType(context),
			`Invalid ${context}: expected object.`,
		);
	}
}

function assertStringField(record: Record<string, unknown>, key: string, context: string): void {
	if (typeof record[key] !== 'string') {
		throw invalidPayloadShapeError(
			contextPayloadType(context),
			`Invalid ${context}: expected ${key} string.`,
		);
	}
}

function assertOptionalStringField(
	record: Record<string, unknown>,
	key: string,
	context: string,
): void {
	if (record[key] !== undefined && typeof record[key] !== 'string') {
		throw invalidPayloadShapeError(
			contextPayloadType(context),
			`Invalid ${context}: expected ${key} string.`,
		);
	}
}

function assertBooleanField(record: Record<string, unknown>, key: string, context: string): void {
	if (typeof record[key] !== 'boolean') {
		throw invalidPayloadShapeError(
			contextPayloadType(context),
			`Invalid ${context}: expected ${key} boolean.`,
		);
	}
}

function assertLiteralField(
	record: Record<string, unknown>,
	key: string,
	expected: string,
	context: string,
): void {
	if (record[key] !== expected) {
		throw invalidPayloadShapeError(
			contextPayloadType(context),
			`Invalid ${context}: expected ${key} "${expected}".`,
		);
	}
}

function assertStringArrayField(
	record: Record<string, unknown>,
	key: string,
	context: string,
): void {
	if (!Array.isArray(record[key])) {
		throw invalidPayloadShapeError(
			contextPayloadType(context),
			`Invalid ${context}: expected ${key} array.`,
		);
	}

	for (const value of record[key]) {
		if (typeof value !== 'string') {
			throw invalidPayloadShapeError(
				contextPayloadType(context),
				`Invalid ${context}: expected ${key} string array.`,
			);
		}
	}
}

function assertNonNegativeIntegerArrayField(
	record: Record<string, unknown>,
	key: string,
	context: string,
): void {
	if (!Array.isArray(record[key])) {
		throw invalidPayloadShapeError(
			contextPayloadType(context),
			`Invalid ${context}: expected ${key} array.`,
		);
	}

	for (const value of record[key]) {
		if (typeof value !== 'number' || !Number.isInteger(value) || value < 0) {
			throw invalidPayloadShapeError(
				contextPayloadType(context),
				`Invalid ${context}: expected ${key} non-negative integer array.`,
			);
		}
	}
}

function assertOptionalStringArrayField(
	record: Record<string, unknown>,
	key: string,
	context: string,
): void {
	if (record[key] !== undefined) {
		assertStringArrayField(record, key, context);
	}
}

function assertOptionalArrayField(
	record: Record<string, unknown>,
	key: string,
	context: string,
