		return;
	}

	throw invalidPayloadShapeError(
		contextPayloadType(context),
		`Invalid ${context}: expected scope request, container, or page.`,
	);
}

function assertOptionalSharedDependencies(record: Record<string, unknown>, context: string): void {
	if (record.dependencies === undefined) return;
	if (!Array.isArray(record.dependencies)) {
		throw invalidPayloadShapeError(
			contextPayloadType(context),
			`Invalid ${context}: expected dependencies array.`,
		);
	}

	for (const [index, dependency] of record.dependencies.entries()) {
		const dependencyContext = `${context}.dependencies[${index}]`;
		assertRecordShape(dependency, dependencyContext);
		assertStringField(dependency, 'definitionId', dependencyContext);
		assertStringField(dependency, 'definitionName', dependencyContext);
	}
}

function assertOptionalSharedReturnProperties(
	record: Record<string, unknown>,
	context: string,
): void {
	if (record.returnProperties === undefined) return;
	if (!Array.isArray(record.returnProperties)) {
		throw invalidPayloadShapeError(
			contextPayloadType(context),
			`Invalid ${context}: expected returnProperties array.`,
		);
	}

	for (const [index, property] of record.returnProperties.entries()) {
		const propertyContext = `${context}.returnProperties[${index}]`;
		assertRecordShape(property, propertyContext);
		assertStringField(property, 'kind', propertyContext);
		assertStringField(property, 'name', propertyContext);

		if (property.kind === 'graph') {
			assertStringField(property, 'graphNodeId', propertyContext);
			assertStringArrayField(property, 'path', propertyContext);
			continue;
		}

		if (property.kind === 'method') continue;

		throw invalidPayloadShapeError(
			contextPayloadType(propertyContext),
			`Invalid ${propertyContext}: expected graph or method return property kind.`,
		);
	}
}

function assertOptionalAsyncComputedSnapshot(
	record: Record<string, unknown>,
	context: string,
): void {
	if (record.snapshot === undefined) return;

	const snapshotContext = `${context}.snapshot`;
	assertRecordShape(record.snapshot, snapshotContext);
	assertStringField(record.snapshot, 'status', snapshotContext);
	assertNonNegativeIntegerField(record.snapshot, 'version', snapshotContext);

	if (record.snapshot.status === 'idle') {
		if (record.snapshot.version !== 0) {
			throw invalidPayloadShapeError(
				contextPayloadType(snapshotContext),
				`Invalid ${snapshotContext}: expected idle version 0.`,
			);
		}
		return;
	}

	if (
		record.snapshot.status !== 'pending' &&
		record.snapshot.status !== 'fulfilled' &&
		record.snapshot.status !== 'rejected'
	) {
		throw invalidPayloadShapeError(
			contextPayloadType(snapshotContext),
			`Invalid ${snapshotContext}: expected supported async snapshot status.`,
		);
	}

	if (!('key' in record.snapshot)) {
		throw invalidPayloadShapeError(
			contextPayloadType(snapshotContext),
			`Invalid ${snapshotContext}: expected key.`,
		);
	}
	assertSerializedGraphPayload(record.snapshot.key, `${snapshotContext}.key`);

	if (record.snapshot.status === 'fulfilled' && !('value' in record.snapshot)) {
		throw invalidPayloadShapeError(
			contextPayloadType(snapshotContext),
			`Invalid ${snapshotContext}: expected value.`,
		);
	}
	if (record.snapshot.status === 'fulfilled') {
		assertSerializedGraphPayload(record.snapshot.value, `${snapshotContext}.value`);
	}

	if (record.snapshot.status === 'rejected' && !('error' in record.snapshot)) {
		throw invalidPayloadShapeError(
			contextPayloadType(snapshotContext),
			`Invalid ${snapshotContext}: expected error.`,
		);
	}
	if (record.snapshot.status === 'rejected') {
		assertSerializedGraphPayload(record.snapshot.error, `${snapshotContext}.error`);
	}
}

function assertSerializedGraphPayload(value: unknown, context: string): void {
	assertRecordShape(value, context);
	if (value.version !== 1) {
		throw invalidPayloadShapeError(
			contextPayloadType(context),
			`Invalid ${context}: expected version 1.`,
		);
	}
	if (!('root' in value)) {
		throw invalidPayloadShapeError(
			contextPayloadType(context),
			`Invalid ${context}: expected root.`,
		);
	}
	if (!Array.isArray(value.records)) {
		throw invalidPayloadShapeError(
			contextPayloadType(context),
			`Invalid ${context}: expected records array.`,
		);
	}

	const recordIds = new Set<number>();
	const recordsById = new Map<number, Record<string, unknown>>();
	for (const [index, record] of value.records.entries()) {
		const recordContext = `${context}.records[${index}]`;
		assertSerializedRecord(record, recordContext);
		const recordId = (record as { readonly id: number }).id;
		if (recordIds.has(recordId)) {
			throw invalidPayloadShapeError(
				contextPayloadType(recordContext),
				`Invalid ${recordContext}: duplicate record id ${String(recordId)}.`,
			);
		}
		recordIds.add(recordId);
		recordsById.set(recordId, record as Record<string, unknown>);
	}

	assertSerializedSlot(value.root, `${context}.root`);
	assertSerializedSlotReferences(value.root, `${context}.root`, recordIds);
	for (const [index, record] of value.records.entries()) {
		const recordContext = `${context}.records[${index}]`;
		const recordObject = record as Record<string, unknown>;
		assertSerializedRecordReferences(recordObject, recordContext, recordIds);
		assertArrayBufferViewRecordRange(recordObject, recordContext, recordsById);
	}
}

function assertSerializedRecord(value: unknown, context: string): void {
	assertRecordShape(value, context);
	assertNonNegativeIntegerField(value, 'id', context);
	assertStringField(value, 'type', context);

	if (value.type === 'object') {
		assertSerializedEntries(value, 'fields', context, 'field');
		return;
	}
	if (value.type === 'array') {
		assertSerializedSlotArray(value.items, `${context}.items`);
		return;
	}
	if (value.type === 'map') {
		assertSerializedEntries(value, 'entries', context, 'entry');
		return;
	}
	if (value.type === 'set') {
		assertSerializedSlotArray(value.values, `${context}.values`);
		return;
	}
	if (value.type === 'date' || value.type === 'url') {
		assertStringField(value, 'value', context);
		if (value.type === 'date') assertIsoDateString(value.value, context);
		if (value.type === 'url') assertUrlString(value.value, context);
		return;
	}
	if (value.type === 'regexp') {
		assertStringField(value, 'source', context);
		assertStringField(value, 'flags', context);
		assertRegExpParts(value.source, value.flags, context);
		return;
	}
	if (value.type === 'array-buffer') {
		assertByteArrayField(value, 'bytes', context);
		return;
	}
	if (value.type === 'typed-array') {
		assertStringField(value, 'arrayType', context);
		assertSupportedTypedArrayType(value.arrayType, context);
		assertSerializedSlot(value.buffer, `${context}.buffer`);
		assertNonNegativeIntegerField(value, 'byteOffset', context);
		assertNonNegativeIntegerField(value, 'length', context);
		return;
	}
	if (value.type === 'data-view') {
		assertSerializedSlot(value.buffer, `${context}.buffer`);
		assertNonNegativeIntegerField(value, 'byteOffset', context);
		assertNonNegativeIntegerField(value, 'byteLength', context);
		return;
	}

	throw invalidPayloadShapeError(
		contextPayloadType(context),
		`Invalid ${context}: expected supported serialized record type.`,
	);
}

function assertSupportedTypedArrayType(value: unknown, context: string): void {
	if (
		value === 'Int8Array' ||
		value === 'Uint8Array' ||
		value === 'Uint8ClampedArray' ||
		value === 'Int16Array' ||
		value === 'Uint16Array' ||
		value === 'Int32Array' ||
		value === 'Uint32Array' ||
		value === 'Float32Array' ||
		value === 'Float64Array' ||
		value === 'BigInt64Array' ||
		value === 'BigUint64Array'
	) {
		return;
	}

	throw invalidPayloadShapeError(
		contextPayloadType(context),
		`Invalid ${context}: expected supported typed array type.`,
	);
}

function assertSerializedRecordReferences(
	record: Record<string, unknown>,
	context: string,
	recordIds: ReadonlySet<number>,
): void {
	if (record.type === 'object') {
		assertSerializedEntryReferences(record.fields, `${context}.fields`, recordIds, false);
		return;
	}
	if (record.type === 'array') {
		assertSerializedSlotArrayReferences(record.items, `${context}.items`, recordIds);
		return;
	}
	if (record.type === 'map') {
		assertSerializedEntryReferences(record.entries, `${context}.entries`, recordIds, true);
		return;
	}
	if (record.type === 'set') {
		assertSerializedSlotArrayReferences(record.values, `${context}.values`, recordIds);
		return;
	}
	if (record.type === 'typed-array' || record.type === 'data-view') {
		assertSerializedSlotReferences(record.buffer, `${context}.buffer`, recordIds);
	}
}

function assertSerializedEntryReferences(
	value: unknown,
	context: string,
	recordIds: ReadonlySet<number>,
	keyIsSlot: boolean,
): void {
	if (!Array.isArray(value)) return;

	for (const [index, entry] of value.entries()) {
		if (!Array.isArray(entry) || entry.length !== 2) continue;
		if (keyIsSlot) {
			assertSerializedSlotReferences(entry[0], `${context}[${index}][0]`, recordIds);
		}
		assertSerializedSlotReferences(entry[1], `${context}[${index}][1]`, recordIds);
	}
}

function assertSerializedSlotArrayReferences(
	value: unknown,
	context: string,
	recordIds: ReadonlySet<number>,
): void {
	if (!Array.isArray(value)) return;

	for (const [index, slot] of value.entries()) {
		assertSerializedSlotReferences(slot, `${context}[${index}]`, recordIds);
	}
}

function assertSerializedSlotReferences(
	value: unknown,
	context: string,
	recordIds: ReadonlySet<number>,
): void {
	if (!isRecord(value) || !('$ref' in value) || typeof value.$ref !== 'number') return;
	if (!Number.isInteger(value.$ref) || value.$ref < 0) {
		throw invalidPayloadShapeError(
			contextPayloadType(context),
			`Invalid ${context}: expected $ref non-negative integer.`,
		);
	}
	if (recordIds.has(value.$ref)) return;

	throw invalidPayloadShapeError(
		contextPayloadType(context),
		`Invalid ${context}: unknown record ref ${String(value.$ref)}.`,
	);
}

function assertArrayBufferViewRecordRange(
	record: Record<string, unknown>,
	context: string,
	recordsById: ReadonlyMap<number, Record<string, unknown>>,
): void {
	if (record.type !== 'typed-array' && record.type !== 'data-view') return;

	const bufferRecord = referencedArrayBufferRecord(record.buffer, context, recordsById);
	const bytes = bufferRecord.bytes;
	if (!Array.isArray(bytes)) return;

	const byteOffset = record.byteOffset as number;
	if (record.type === 'typed-array') {
		const elementByteLength = typedArrayElementByteLength(record.arrayType);
		if (byteOffset % elementByteLength !== 0) {
			throw invalidPayloadShapeError(
				contextPayloadType(context),
				`Invalid ${context}: typed-array byteOffset must align to element byte length.`,
			);
		}
		const byteLength = (record.length as number) * elementByteLength;
		if (byteOffset + byteLength > bytes.length) {
			throw invalidPayloadShapeError(
				contextPayloadType(context),
				`Invalid ${context}: typed-array byte range exceeds referenced array-buffer.`,
			);
		}
		return;
	}

	const byteLength = record.byteLength as number;
	if (byteOffset + byteLength > bytes.length) {
		throw invalidPayloadShapeError(
			contextPayloadType(context),
			`Invalid ${context}: data-view byte range exceeds referenced array-buffer.`,
		);
	}
}

function referencedArrayBufferRecord(
	value: unknown,
	context: string,
	recordsById: ReadonlyMap<number, Record<string, unknown>>,
): Record<string, unknown> {
	if (!isRecord(value) || typeof value.$ref !== 'number') {
		throw invalidPayloadShapeError(
			contextPayloadType(context),
			`Invalid ${context}: expected buffer array-buffer ref.`,
		);
	}

	const record = recordsById.get(value.$ref);
	if (record?.type !== 'array-buffer') {
		throw invalidPayloadShapeError(
			contextPayloadType(context),
			`Invalid ${context}: expected buffer array-buffer ref.`,
		);
	}

	return record;
}

function typedArrayElementByteLength(value: unknown): number {
	if (value === 'Int8Array' || value === 'Uint8Array' || value === 'Uint8ClampedArray') {
		return 1;
	}
	if (value === 'Int16Array' || value === 'Uint16Array') return 2;
	if (value === 'Int32Array' || value === 'Uint32Array' || value === 'Float32Array') {
		return 4;
	}
	return 8;
}

function assertSerializedEntries(
	record: Record<string, unknown>,
	key: string,
	context: string,
	entryName: string,
): void {
	const entries = record[key];
	if (!Array.isArray(entries)) {
		throw invalidPayloadShapeError(
			contextPayloadType(context),
			`Invalid ${context}: expected ${key} array.`,
		);
	}

	for (const [index, entry] of entries.entries()) {
		if (!Array.isArray(entry) || entry.length !== 2) {
			throw invalidPayloadShapeError(
				contextPayloadType(context),
				`Invalid ${context}.${key}[${index}]: expected ${entryName} pair.`,
			);
		}
		if (key === 'fields' && typeof entry[0] !== 'string') {
			throw invalidPayloadShapeError(
				contextPayloadType(context),
				`Invalid ${context}.${key}[${index}]: expected field name string.`,
			);
		} else if (key === 'entries') {
			assertSerializedSlot(entry[0], `${context}.${key}[${index}][0]`);
		}
		assertSerializedSlot(entry[1], `${context}.${key}[${index}][1]`);
	}
}

function assertSerializedSlotArray(value: unknown, context: string): void {
	if (!Array.isArray(value)) {
		throw invalidPayloadShapeError(
			contextPayloadType(context),
			`Invalid ${context}: expected array.`,
		);
	}

	for (const [index, slot] of value.entries()) {
		assertSerializedSlot(slot, `${context}[${index}]`);
	}
}

function assertByteArrayField(record: Record<string, unknown>, key: string, context: string): void {
	if (!Array.isArray(record[key])) {
		throw invalidPayloadShapeError(
			contextPayloadType(context),
			`Invalid ${context}: expected ${key} array.`,
		);
	}

	for (const value of record[key]) {
		if (typeof value !== 'number' || !Number.isInteger(value) || value < 0 || value > 255) {
			throw invalidPayloadShapeError(
				contextPayloadType(context),
				`Invalid ${context}: expected ${key} byte array.`,
			);
		}
	}
}

function assertSerializedSlot(value: unknown, context: string): void {
	if (
		value === null ||
		typeof value === 'string' ||
		typeof value === 'number' ||
		typeof value === 'boolean'
	) {
		return;
	}
	if (!isRecord(value)) {
		throw invalidPayloadShapeError(
			contextPayloadType(context),
			`Invalid ${context}: expected serialized slot.`,
		);
	}
	if ('$ref' in value) {
		assertNonNegativeIntegerField(value, '$ref', context);
		return;
	}
	if (value.$type === 'undefined') return;
	if (value.$type === 'bigint') {
		assertStringField(value, 'value', context);
		assertBigIntString(value.value, context);
		return;
	}
	if (value.$type === 'date' || value.$type === 'url') {
		assertStringField(value, 'value', context);
		if (value.$type === 'date') assertIsoDateString(value.value, context);
		if (value.$type === 'url') assertUrlString(value.value, context);
		return;
	}
	if (value.$type === 'regexp') {
		assertStringField(value, 'source', context);
		assertStringField(value, 'flags', context);
		assertRegExpParts(value.source, value.flags, context);
		return;
	}

	throw invalidPayloadShapeError(
		contextPayloadType(context),
		`Invalid ${context}: expected serialized slot.`,
	);
}

function assertNonNegativeIntegerField(
	record: Record<string, unknown>,
	key: string,
	context: string,
): void {
	if (typeof record[key] !== 'number' || !Number.isInteger(record[key]) || record[key] < 0) {
		throw invalidPayloadShapeError(
			contextPayloadType(context),
			`Invalid ${context}: expected ${key} non-negative integer.`,
		);
	}
}

function assertBigIntString(value: unknown, context: string): void {
	if (typeof value === 'string' && /^-?(0|[1-9]\d*)$/.test(value)) return;

	throw invalidPayloadShapeError(
		contextPayloadType(context),
		`Invalid ${context}: expected bigint string.`,
	);
}

function assertIsoDateString(value: unknown, context: string): void {
	if (typeof value === 'string') {
		const date = new Date(value);
		if (!Number.isNaN(date.getTime()) && date.toISOString() === value) return;
	}

	throw invalidPayloadShapeError(
		contextPayloadType(context),
		`Invalid ${context}: expected ISO date string.`,
	);
}

function assertUrlString(value: unknown, context: string): void {
	if (typeof value === 'string') {
		try {
			new URL(value);
			return;
		} catch {
			// Report as a payload diagnostic below.
		}
	}

	throw invalidPayloadShapeError(
		contextPayloadType(context),
		`Invalid ${context}: expected valid URL string.`,
	);
}

function assertRegExpParts(source: unknown, flags: unknown, context: string): void {
	if (typeof source === 'string' && typeof flags === 'string') {
		try {
			new RegExp(source, flags);
			return;
		} catch {
			// Report as a payload diagnostic below.
		}
	}

	throw invalidPayloadShapeError(
		contextPayloadType(context),
		`Invalid ${context}: expected valid regexp pattern and flags.`,
	);
}

function assertStateValueKind(record: Record<string, unknown>, context: string): void {
	if (
		record.valueKind !== 'scalar' &&
		record.valueKind !== 'object' &&
		record.valueKind !== 'array' &&
		record.valueKind !== 'unknown'
	) {
		throw invalidPayloadShapeError(
			contextPayloadType(context),
			'Invalid ' + context + ': expected valueKind scalar, object, array, or unknown.',
		);
	}
}

function assertCommentAnchor(value: unknown, context: string): void {
	assertRecordShape(value, context);
	assertLiteralField(value, 'strategy', 'dom-order-comment', context);
	assertNonNegativeIntegerField(value, 'index', context);
}

function assertAsyncBoundaryReads(value: unknown, context: string): void {
	if (!Array.isArray(value)) {
		throw invalidPayloadShapeError(
			contextPayloadType(context),
			`Invalid ${context}: expected asyncReads array.`,
		);
	}

	for (const [index, read] of value.entries()) {
		const readContext = `${context}.asyncRead[${index}]`;
		assertRecordShape(read, readContext);
		assertStringField(read, 'source', readContext);
		assertStringField(read, 'graphNodeId', readContext);
		assertStringArrayField(read, 'path', readContext);
		assertOptionalStringField(read, 'runnerSymbolId', readContext);
	}
}

function assertOptionalStringRecord(value: unknown, context: string): void {
	if (value === undefined) return;
	assertRecordShape(value, context);
	for (const [key, entry] of Object.entries(value)) {
		if (typeof entry !== 'string') {
			throw invalidPayloadShapeError(
				contextPayloadType(context),
				`Invalid ${context}.${key}: expected string.`,
			);
		}
	}
}

function assertOptionalDomUpdateTarget(value: unknown, context: string): void {
	if (value === undefined) return;

	assertRecordShape(value, context);
	if (value.kind === 'text') return;
	if (value.kind === 'class') return;
	if (value.kind === 'style') return;
	if (value.kind === 'attribute') {
		if (typeof value.name !== 'string') {
			throw invalidPayloadShapeError(
				contextPayloadType(context),
				`Invalid ${context}: expected attribute name string.`,
			);
		}
		return;
	}
	if (value.kind === 'property') {
		if (typeof value.name !== 'string') {
			throw invalidPayloadShapeError(
				contextPayloadType(context),
				`Invalid ${context}: expected property name string.`,
			);
		}
		return;
	}

	throw invalidPayloadShapeError(
		contextPayloadType(context),
		`Invalid ${context}: expected supported DOM update target kind.`,
	);
}

function assertSyncPolicy(value: unknown, context: string): void {
	assertRecordShape(value, context);

	if ('branches' in value) {
		if (!Array.isArray(value.branches)) {
			throw invalidPayloadShapeError(
				contextPayloadType(context),
				`Invalid ${context}: expected branches array.`,
			);
		}

		for (const [index, branch] of value.branches.entries()) {
			assertSyncPolicyBranch(branch, `${context}.branch[${index}]`);
		}
		return;
	}

	assertSyncPolicyBranch(value, context);
}

function assertSyncPolicyBranch(value: unknown, context: string): void {
	assertRecordShape(value, context);
	assertSyncPolicyCondition(value.when, `${context}.when`);

	if (!Array.isArray(value.actions)) {
		throw invalidPayloadShapeError(
			contextPayloadType(context),
			`Invalid ${context}: expected actions array.`,
		);
	}

	for (const action of value.actions) {
		if (action !== 'preventDefault' && action !== 'stopPropagation') {
			throw invalidPayloadShapeError(
				contextPayloadType(context),
				`Invalid ${context}: expected supported sync action.`,
			);
		}
	}
}

function assertSyncPolicyCondition(value: unknown, context: string): void {
	assertRecordShape(value, context);

	if (value.type === 'and' || value.type === 'or') {
		if (!Array.isArray(value.conditions)) {
			throw invalidPayloadShapeError(
				contextPayloadType(context),
				`Invalid ${context}: expected conditions array.`,
			);
		}

		for (const [index, condition] of value.conditions.entries()) {
			assertSyncPolicyCondition(condition, `${context}.condition[${index}]`);
		}
		return;
	}

	if (value.type === 'not') {
		assertSyncPolicyCondition(value.condition, `${context}.condition`);
		return;
	}

	if (value.type === 'graph-truthy') {
		assertStringField(value, 'graphNodeId', context);
		assertOptionalStringArrayField(value, 'path', context);
		return;
	}

	if (value.type === 'constant-truthy') {
		if (!('value' in value)) {
			throw invalidPayloadShapeError(
				contextPayloadType(context),
				`Invalid ${context}: expected value.`,
			);
		}
		return;
	}

	if (value.type === 'event-equals') {
		assertStringField(value, 'field', context);
		if (!('value' in value)) {
			throw invalidPayloadShapeError(
				contextPayloadType(context),
				`Invalid ${context}: expected value.`,
			);
		}
		return;
	}

	throw invalidPayloadShapeError(
		contextPayloadType(context),
		`Invalid ${context}: expected supported condition type.`,
	);
}

export function payloadInvalidError(
	payloadType: RuntimePayloadType,
	message: string,
	why: string,
	suggestions: ReadonlyArray<{ readonly message: string }>,
): RuntimePayloadError {
	return new RuntimePayloadError({
		code: 'MARKLESS_PAYLOAD_INVALID',
		severity: 'error',
		phase: 'payload',
		title: 'Invalid resumability payload',
		message,
		why,
		payloadType,
		payloadScript: payloadScriptSelector(payloadType),
		suggestions,
		docsUrl: 'https://markless.dev/errors/MARKLESS_PAYLOAD_INVALID',
	});
}

export function invalidPayloadShapeError(
	payloadType: RuntimePayloadType,
	message: string,
): RuntimePayloadError {
	return payloadInvalidError(
		payloadType,
		message,
		`The ${payloadType} payload did not match the resumability protocol shape required by this runtime.`,
		[
			{
				message: `Regenerate the ${payloadType} payload with the matching markless compiler/runtime version.`,
			},
		],
	);
}

function protocolVersionMismatchError(
	payloadType: RuntimePayloadType,
	actualVersion: unknown,
): RuntimePayloadError {
	const supportedVersions =
		payloadType === 'markless/state'
			? `${String(ASYNC_PROTOCOL_VERSION)} or ${String(STORAGE_PROTOCOL_VERSION)}`
			: String(ASYNC_PROTOCOL_VERSION);
	return new RuntimePayloadError({
		code: 'MARKLESS_PROTOCOL_VERSION_MISMATCH',
		severity: 'error',
		phase: 'payload',
		title: 'Unsupported resumability protocol version',
		message: `Unsupported ${payloadType} protocol version ${String(actualVersion)}.`,
		why: `The ${payloadType} payload was produced for protocol version ${String(actualVersion)}, but this runtime can only decode version ${supportedVersions}.`,
		payloadType,
		payloadScript: payloadScriptSelector(payloadType),
		expectedVersion: ASYNC_PROTOCOL_VERSION,
		actualVersion,
		suggestions: [
			{
				message: 'Use matching markless compiler and runtime package versions.',
			},
		],
		docsUrl: 'https://markless.dev/errors/MARKLESS_PROTOCOL_VERSION_MISMATCH',
	});
}

function contextPayloadType(context: string): RuntimePayloadType {
	return context.startsWith('markless/state') ? 'markless/state' : 'markless/view';
}

export function payloadScriptSelector(type: RuntimePayloadType): string {
	return `script[type="${type}"]`;
}

import { ASYNC_BOUNDARY_ARM } from './async-boundary-arm.ts';
import { ASYNC_PROTOCOL_VERSION, STORAGE_PROTOCOL_VERSION } from './protocol-constants.ts';

export { ASYNC_BOUNDARY_ARM, ASYNC_PROTOCOL_VERSION, STORAGE_PROTOCOL_VERSION };

export type ProtocolAsyncBoundaryArm = (typeof ASYNC_BOUNDARY_ARM)[keyof typeof ASYNC_BOUNDARY_ARM];

export type ProtocolSyncPolicyCondition =
	| {
			readonly type: 'and';
			readonly conditions: ReadonlyArray<ProtocolSyncPolicyCondition>;
	  }
	| {
			readonly type: 'or';
			readonly conditions: ReadonlyArray<ProtocolSyncPolicyCondition>;
	  }
	| {
			readonly type: 'not';
			readonly condition: ProtocolSyncPolicyCondition;
	  }
	| {
			readonly type: 'graph-truthy';
			readonly graphNodeId: string;
			readonly path?: ReadonlyArray<string>;
	  }
	| {
			readonly type: 'constant-truthy';
			readonly value: unknown;
	  }
	| {
			readonly type: 'event-equals';
			readonly field: string;
			readonly value: unknown;
	  };

export type ProtocolSyncPolicyBranch = {
	readonly when: ProtocolSyncPolicyCondition;
	readonly actions: ReadonlyArray<'preventDefault' | 'stopPropagation'>;
};

export type ProtocolSyncPolicy =
	| ProtocolSyncPolicyBranch
	| {
			readonly branches: ReadonlyArray<ProtocolSyncPolicyBranch>;
	  };

export const PROTOCOL_EVENT_ACTION_KIND = {
	event: 'event',
	externalDelegate: 'external-delegate',
} as const;

export type ProtocolEventActionKind =
	(typeof PROTOCOL_EVENT_ACTION_KIND)[keyof typeof PROTOCOL_EVENT_ACTION_KIND];

export type ProtocolEventAction = {
	readonly kind: typeof PROTOCOL_EVENT_ACTION_KIND.externalDelegate;
	readonly owner: string;
};

export type ProtocolEventRecord = {
	readonly hostNodeId: string;
	readonly eventName: string;
	readonly syncPolicy?: ProtocolSyncPolicy;
	readonly symbolIds: ReadonlyArray<string>;
	readonly action?: ProtocolEventAction;
};

export function protocolEventActionKind(
	record: Pick<ProtocolEventRecord, 'action'>,
): ProtocolEventActionKind {
	return record.action?.kind ?? PROTOCOL_EVENT_ACTION_KIND.event;
}

const PROTOCOL_EVENT_ACTION_DISPATCHES_MARKLESS = {
	[PROTOCOL_EVENT_ACTION_KIND.event]: true,
	[PROTOCOL_EVENT_ACTION_KIND.externalDelegate]: false,
} as const satisfies Record<ProtocolEventActionKind, boolean>;

export function protocolEventDispatchesMarkless(
	record: Pick<ProtocolEventRecord, 'action'>,
): boolean {
	return PROTOCOL_EVENT_ACTION_DISPATCHES_MARKLESS[protocolEventActionKind(record)];
}

export type ProtocolStatePayload = {
	readonly version: typeof ASYNC_PROTOCOL_VERSION | typeof STORAGE_PROTOCOL_VERSION;
	readonly cells: ReadonlyArray<{
		readonly graphNodeId: string;
		readonly name: string;
		readonly valueKind: 'scalar' | 'object' | 'array' | 'unknown';
		readonly value?: unknown;
		// Live-value channel (need 14): CSR mounts seed cells (page props) whose
		// value never crosses HTML, so it travels as-is instead of a serialized
		// envelope. Hosts serving a payload script must envelope-encode these via
		// serializeRuntimeStateCells first — payload decoding rejects the field.
		readonly directValue?: unknown;
	}>;
	readonly computed: ReadonlyArray<{
		readonly graphNodeId: string;
		readonly name: string;
		readonly async: boolean;
		// Sync computeds only: the update symbol that recomputes this node on resume.
		readonly deriveSymbolId?: string;
		readonly dependencies?: ReadonlyArray<{
			readonly graphNodeId: string;
			readonly path: ReadonlyArray<string>;
		}>;
		readonly snapshot?:
			| {
					readonly status: 'idle';
					readonly version: 0;
			  }
			| {
					readonly status: 'pending';
					readonly version: number;
					readonly key: unknown;
			  }
			| {
					readonly status: 'fulfilled';
					readonly version: number;
					readonly key: unknown;
					readonly value: unknown;
			  }
			| {
					readonly status: 'rejected';
					readonly version: number;
					readonly key: unknown;
					readonly error: unknown;
			  };
	}>;
	readonly sharedDefinitions?: ReadonlyArray<{
		readonly id: string;
		readonly name: string;
		readonly exportedName: string;
		readonly scope?: 'request' | 'container' | 'page';
		readonly version: number;
		readonly graphNodeIds: ReadonlyArray<string>;
		readonly dependencies?: ReadonlyArray<{
			readonly definitionId: string;
			readonly definitionName: string;
		}>;
		readonly returnProperties?: ReadonlyArray<
			| {
					readonly kind: 'graph';
					readonly name: string;
					readonly graphNodeId: string;
					readonly path: ReadonlyArray<string>;
			  }
			| {
					readonly kind: 'method';
					readonly name: string;
			  }
		>;
	}>;
	readonly storage?: ReadonlyArray<{
		readonly graphNodeId: string;
		readonly key: string;
	}>;
};

// D3 arm-relative coordinates: records inside an async boundary arm index
// from the boundary's start anchor (locator index 0 names the first element
// after it), so arms stay closed, movable, replaceable, streamable units.
// Arm-scoped branch records resolve their anchors in the arm's own
// arm-branch comment census; escalated records carry no anchors.
export type ProtocolArmBranchRecord = {
	readonly id: string;
	readonly testReads: ReadonlyArray<{
		readonly source: string;
		readonly graphNodeId: string;
		readonly path: ReadonlyArray<string>;
	}>;
	readonly symbolId?: string;
	readonly armTests?: ReadonlyArray<unknown>;
	readonly declaredEmptyArms?: ReadonlyArray<number>;
	readonly startAnchor?: { readonly strategy: 'arm-branch-comment'; readonly index: number };
	readonly endAnchor?: { readonly strategy: 'arm-branch-comment'; readonly index: number };
	readonly armRecords?: NonNullable<ProtocolViewPayload['branches']>[number]['armRecords'];
};

export type ProtocolArmRecordSet = {
	readonly locators: ReadonlyArray<{
		readonly hostNodeId: string;
		readonly strategy: 'arm-relative';
		readonly index: number;
		readonly tagName: string;
	}>;
	readonly events: ProtocolViewPayload['events'];
	readonly domUpdates?: ProtocolViewPayload['domUpdates'];
	readonly behaviors: ProtocolViewPayload['behaviors'];
	readonly elementHandles: ProtocolViewPayload['elementHandles'];
	readonly keyedRepeats?: ProtocolViewPayload['keyedRepeats'];
	readonly branches?: ReadonlyArray<ProtocolArmBranchRecord>;
};

// A streamed arm carries its served-arm discriminator beside the record set,
// avoiding a second snapshot scan during pre-resume adoption.
export type ProtocolStreamedArmPatch = readonly [
	arm: ProtocolAsyncBoundaryArm,
	records: ProtocolArmRecordSet,
];

export type ProtocolViewPayload = {
	readonly version: typeof ASYNC_PROTOCOL_VERSION;
	// Async runner transport is independent from authored boundary reads. The
	// compiler emits the dependency closure needed to reconstruct the client
	// graph; optionality preserves protocol-v1 payloads with no async runners.
	readonly asyncRunners?: Readonly<Record<string, string>>;
	readonly locators: ReadonlyArray<{
		readonly hostNodeId: string;
		readonly strategy: 'dom-order';
		readonly index: number;
		readonly tagName: string;
	}>;
	readonly events: ReadonlyArray<ProtocolEventRecord>;
	readonly domUpdates: ReadonlyArray<{
		readonly hostNodeId: string;
		readonly source: string;
		readonly graphNodeId: string;
		readonly path: ReadonlyArray<string>;
		readonly target?:
			| {
					readonly kind: 'text';
					readonly prefix?: string;
					readonly suffix?: string;
					readonly trueValue?: string;
					readonly falseValue?: string;
			  }
			| {
					readonly kind: 'attribute';
					readonly name: string;
			  }
			| {
					readonly kind: 'property';
					readonly name: string;
			  }
			| {
					readonly kind: 'class';
					readonly trueValue?: string;
					readonly falseValue?: string;
			  }
			| {
					readonly kind: 'style';
			  };
		readonly symbolId?: string;
	}>;
	readonly behaviors: ReadonlyArray<{
		readonly hostNodeId: string;
		readonly source: string;
		readonly functionSource: string;
		readonly inputSources: ReadonlyArray<string>;
		readonly inputValues?: ReadonlyArray<unknown>;
		readonly inputGraphReads?: ReadonlyArray<{
			readonly inputIndex: number;
			readonly source: string;
			readonly graphNodeId: string;
			readonly path: ReadonlyArray<string>;
		}>;
		readonly symbolId?: string;
	}>;
	readonly elementHandles: ReadonlyArray<{
		readonly hostNodeId: string;
		readonly handleId: string;
		readonly name: string;
	}>;
	readonly keyedRepeats?: ReadonlyArray<{
		readonly id: string;
		readonly parentHostNodeId: string;
		readonly collectionGraphNodeId?: string;
		readonly collectionPath: ReadonlyArray<string>;
		readonly keyPath: ReadonlyArray<string>;
		readonly itemName: string;
		readonly rowElementCount: number;
		readonly rowEvents: ReadonlyArray<{
			readonly hostPath: ReadonlyArray<number>;
			readonly eventName: string;
			readonly symbolIds: ReadonlyArray<string>;
			readonly syncPolicy?: ProtocolSyncPolicy;
		}>;
	}>;
	readonly branches?: ReadonlyArray<{
		readonly id: string;
		readonly startAnchor: { readonly strategy: 'dom-order-comment'; readonly index: number };
		readonly endAnchor: { readonly strategy: 'dom-order-comment'; readonly index: number };
		readonly symbolId?: string;
		readonly armTests?: ReadonlyArray<unknown>;
		readonly armRecords?: ReadonlyArray<{
			readonly events: ReadonlyArray<{
				readonly hostPath: ReadonlyArray<number>;
				readonly eventName: string;
				readonly symbolIds: ReadonlyArray<string>;
				readonly syncPolicy?: ProtocolSyncPolicy;
				readonly action?: ProtocolEventAction;
			}>;
			readonly domUpdates: ReadonlyArray<Record<string, unknown>>;
			readonly behaviors: ReadonlyArray<Record<string, unknown>>;
			readonly elementHandles: ReadonlyArray<Record<string, unknown>>;
		}>;
		readonly testReads?: ReadonlyArray<{
			readonly source: string;
			readonly graphNodeId: string;
			readonly path: ReadonlyArray<string>;
		}>;
	}>;
	readonly asyncBoundaries: ReadonlyArray<{
		readonly id: string;
		readonly runnerGraphNodeId: string | null;
		readonly initiallyServedArm: ProtocolAsyncBoundaryArm;
		readonly updateSymbolId?: string;
		// A single set is the armized truth for the arm the render actually
		// served (SSR compose / arm-render modules); an array is the compiler's
		// per-arm plan (index 0 = @try, 1 = @pending, 2 = @catch), which is not
		// positionally trustworthy after composition and is never registrable.
		readonly armRecords?: ProtocolArmRecordSet | ReadonlyArray<ProtocolArmRecordSet>;
		readonly startAnchor: {
			readonly strategy: 'dom-order-comment';
			readonly index: number;
		};
		readonly endAnchor: {
			readonly strategy: 'dom-order-comment';
			readonly index: number;
		};
		readonly asyncReads: ReadonlyArray<{
			readonly source: string;
			readonly graphNodeId: string;
			readonly path: ReadonlyArray<string>;
			readonly runnerSymbolId?: string;
		}>;
	}>;
};

export type ProtocolPayloadScripts = {
	readonly state: ProtocolStatePayload;
	readonly view: ProtocolViewPayload;
	readonly stateScript: string;
	readonly viewScript: string;
};

import type { ProtocolStatePayload, ProtocolViewPayload } from './protocol.ts';
import type { ResumeRecordSet } from './resume-record-merge.ts';
import { serializeGraphValue } from './value.ts';

export { mergeResumeRecordDelta, type ResumeRecordSet } from './resume-record-merge.ts';

export type ResumeRecordDeltaClassification =
	| { readonly kind: 'empty' }
	| { readonly kind: 'divergent'; readonly delta: ResumeRecordSet };

// Every protocol record is compared independently by its durable value. Props
// are cells, so cells, computed snapshots, and props all follow this one rule.
// The resulting payload contains only request records that are new or changed.
export function classifyResumeRecordDelta(
	baseline: ResumeRecordSet,
	request: ResumeRecordSet,
): ResumeRecordDeltaClassification {
	// Validate the complete inputs before selecting known keyed records. This
	// keeps an unsupported request-only value from being silently discarded.
	durableComparisonValue(baseline, 'build baseline');
	durableComparisonValue(request, 'request records');
	assertMatchingVersion(baseline.state.version, request.state.version, 'state');
	assertMatchingVersion(baseline.view.version, request.view.version, 'view');

	const state = {
		version: request.state.version,
		cells: divergentRecords(baseline.state.cells, request.state.cells, stateCellKey, 'state cell'),
		computed: divergentRecords(
			baseline.state.computed,
			request.state.computed,
			stateComputedKey,
			'computed',
		),
		...optionalRecordDelta(
			baseline.state,
			request.state,
			'sharedDefinitions',
			(record) => record.id,
			'shared definition',
		),
		...optionalRecordDelta(
			baseline.state,
			request.state,
			'storage',
			(record) => record.graphNodeId,
			'storage',
		),
	} satisfies ProtocolStatePayload;
	const view = {
		version: request.view.version,
		...asyncRunnerDelta(baseline.view, request.view),
		locators: divergentRecords(
			baseline.view.locators,
			request.view.locators,
			(record) => record.hostNodeId,
			'view locator',
		),
		events: divergentRecords(
			baseline.view.events,
			request.view.events,
			(record) => `${record.hostNodeId}\0${record.eventName}`,
			'view event',
		),
		domUpdates: divergentRecords(
			baseline.view.domUpdates,
			request.view.domUpdates,
			(record) => `${record.hostNodeId}\0${record.graphNodeId}\0${record.source}`,
			'DOM update',
		),
		behaviors: divergentRecords(
			baseline.view.behaviors,
			request.view.behaviors,
			(record) => `${record.hostNodeId}\0${record.source}`,
			'behavior',
		),
		elementHandles: divergentRecords(
			baseline.view.elementHandles,
			request.view.elementHandles,
			(record) => `${record.hostNodeId}\0${record.handleId}`,
			'element handle',
		),
		...optionalRecordDelta(
			baseline.view,
			request.view,
			'keyedRepeats',
			(record) => record.id,
			'keyed repeat',
		),
		...optionalRecordDelta(
			baseline.view,
			request.view,
			'branches',
			(record) => record.id,
			'branch',
		),
		asyncBoundaries: divergentRecords(
			baseline.view.asyncBoundaries,
			request.view.asyncBoundaries,
			(record) => record.id,
			'async boundary',
		),
	} satisfies ProtocolViewPayload;
	const delta = { state, view };
	return hasDeltaRecords(delta) ? { kind: 'divergent', delta } : { kind: 'empty' };
}

function stateCellKey(record: ProtocolStatePayload['cells'][number]): string {
	return record.graphNodeId;
}

function stateComputedKey(record: ProtocolStatePayload['computed'][number]): string {
	return record.graphNodeId;
}

function divergentRecords<T>(
	baseline: ReadonlyArray<T>,
	request: ReadonlyArray<T>,
	key: (record: T) => string,
	label: string,
): ReadonlyArray<T> {
	const baselineByKey = uniqueRecords(baseline, key, `build baseline ${label}`);
	const requestByKey = uniqueRecords(request, key, `request ${label}`);
	for (const baselineKey of baselineByKey.keys()) {
		if (!requestByKey.has(baselineKey)) {
			throw new Error(`MARKLESS_RESUME_RECORD_DELTA_REMOVAL_UNSUPPORTED: ${label} ${baselineKey}.`);
		}
	}
	return request.filter((record) => {
		const baselineRecord = baselineByKey.get(key(record));
		return (
			baselineRecord === undefined ||
			durableComparisonValue(baselineRecord, `build baseline ${label}`) !==
				durableComparisonValue(record, `request ${label}`)
		);
	});
}

function uniqueRecords<T>(
	records: ReadonlyArray<T>,
	key: (record: T) => string,
	source: string,
): Map<string, T> {
	const result = new Map<string, T>();
	for (const record of records) {
		const recordKey = key(record);
		if (result.has(recordKey)) {
			throw new Error(`MARKLESS_RESUME_RECORD_DELTA_DUPLICATE_KEY: ${source} ${recordKey}.`);
		}
		result.set(recordKey, record);
	}
	return result;
}

function optionalRecordDelta<
	T extends object,
	K extends {
		[P in keyof T]-?: T[P] extends ReadonlyArray<unknown> | undefined ? P : never;
	}[keyof T],
>(
	baseline: T,
	request: T,
	property: K,
	key: (record: NonNullable<T[K]> extends ReadonlyArray<infer R> ? R : never) => string,
	label: string,
): Partial<Pick<T, K>> {
	const baselineRecords = baseline[property] as ReadonlyArray<never> | undefined;
	const requestRecords = request[property] as ReadonlyArray<never> | undefined;
	if (requestRecords === undefined) {
		if (baselineRecords !== undefined)
			throw new Error(`MARKLESS_RESUME_RECORD_DELTA_REMOVAL_UNSUPPORTED: ${label} set.`);
		return {};
	}
	return {
		[property]: divergentRecords(baselineRecords ?? [], requestRecords, key, label),
	} as Partial<Pick<T, K>>;
}

function asyncRunnerDelta(
	baseline: ProtocolViewPayload,
	request: ProtocolViewPayload,
): Pick<ProtocolViewPayload, 'asyncRunners'> | Record<never, never> {
	if (request.asyncRunners === undefined) {
		if (baseline.asyncRunners !== undefined)
			throw new Error('MARKLESS_RESUME_RECORD_DELTA_REMOVAL_UNSUPPORTED: async runner set.');
		return {};
	}
	const delta: Record<string, string> = {};
	for (const key of Object.keys(baseline.asyncRunners ?? {})) {
		if (!(key in request.asyncRunners))
			throw new Error(`MARKLESS_RESUME_RECORD_DELTA_REMOVAL_UNSUPPORTED: async runner ${key}.`);
	}
	for (const [key, value] of Object.entries(request.asyncRunners)) {
		if (baseline.asyncRunners?.[key] !== value) delta[key] = value;
	}
	return { asyncRunners: delta };
}

function hasDeltaRecords(delta: ResumeRecordSet): boolean {
	return (
		delta.state.cells.length > 0 ||
		delta.state.computed.length > 0 ||
		(delta.state.sharedDefinitions?.length ?? 0) > 0 ||
		(delta.state.storage?.length ?? 0) > 0 ||
		Object.keys(delta.view.asyncRunners ?? {}).length > 0 ||
		delta.view.locators.length > 0 ||
		delta.view.events.length > 0 ||
		delta.view.domUpdates.length > 0 ||
		delta.view.behaviors.length > 0 ||
		delta.view.elementHandles.length > 0 ||
		(delta.view.keyedRepeats?.length ?? 0) > 0 ||
		(delta.view.branches?.length ?? 0) > 0 ||
		delta.view.asyncBoundaries.length > 0
	);
}

function assertMatchingVersion(baseline: number, request: number, payload: string): void {
	if (baseline !== request) {
		throw new Error(
			`MARKLESS_RESUME_RECORD_DELTA_VERSION_MISMATCH: ${payload} ${baseline} !== ${request}.`,
		);
	}
}

function durableComparisonValue(value: unknown, source: string): string {
	const result = serializeGraphValue(value);
	if (!result.ok) {
		const diagnostic = result.diagnostics[0];
		throw new Error(
			`MARKLESS_RESUME_RECORD_DIVERGENCE_UNSERIALIZABLE: ${source} contains ` +
				`${diagnostic?.valueKind ?? 'unsupported'} at ${diagnostic?.statePath ?? '<root>'}.`,
		);
	}
	return JSON.stringify(result.payload);
}

import type { ProtocolStatePayload, ProtocolViewPayload } from './protocol.ts';

export type ResumeRecordSet = {
	readonly state: ProtocolStatePayload;
	readonly view: ProtocolViewPayload;
};

// Payload records win by key without pulling server-only classification into clients.
export function mergeResumeRecordDelta(
	baseline: ResumeRecordSet,
	delta: ResumeRecordSet,
): ResumeRecordSet {
	assertMatchingVersion(baseline.state.version, delta.state.version, 'state');
	assertMatchingVersion(baseline.view.version, delta.view.version, 'view');
	return {
		state: {
			...baseline.state,
			cells: mergeRecords(baseline.state.cells, delta.state.cells, (record) => record.graphNodeId),
			computed: mergeRecords(
				baseline.state.computed,
				delta.state.computed,
				(record) => record.graphNodeId,
			),
			...mergeOptionalRecords(
				baseline.state,
				delta.state,
				'sharedDefinitions',
				(record) => record.id,
			),
			...mergeOptionalRecords(
				baseline.state,
				delta.state,
				'storage',
				(record) => record.graphNodeId,
			),
		},
		view: {
			...baseline.view,
			...mergeAsyncRunners(baseline.view, delta.view),
			locators: mergeRecords(
				baseline.view.locators,
				delta.view.locators,
				(record) => record.hostNodeId,
			),
			events: mergeRecords(
				baseline.view.events,
				delta.view.events,
				(record) => `${record.hostNodeId}\0${record.eventName}`,
			),
			domUpdates: mergeRecords(
				baseline.view.domUpdates,
				delta.view.domUpdates,
				(record) => `${record.hostNodeId}\0${record.graphNodeId}\0${record.source}`,
			),
			behaviors: mergeRecords(
				baseline.view.behaviors,
				delta.view.behaviors,
				(record) => `${record.hostNodeId}\0${record.source}`,
			),
			elementHandles: mergeRecords(
				baseline.view.elementHandles,
				delta.view.elementHandles,
				(record) => `${record.hostNodeId}\0${record.handleId}`,
			),
			...mergeOptionalRecords(
				baseline.view,
				delta.view,
				'keyedRepeats',
				(record) => record.id,
			),
			...mergeOptionalRecords(
				baseline.view,
				delta.view,
				'branches',
				(record) => record.id,
			),
			asyncBoundaries: mergeRecords(
				baseline.view.asyncBoundaries,
				delta.view.asyncBoundaries,
				(record) => record.id,
			),
		},
	};
}

function mergeRecords<T>(
	baseline: ReadonlyArray<T>,
	delta: ReadonlyArray<T>,
	key: (record: T) => string,
): ReadonlyArray<T> {
	const byKey = uniqueRecords(delta, key, 'payload record');
	const merged = baseline.map((record) => byKey.get(key(record)) ?? record);
	const baselineKeys = new Set(baseline.map(key));
	for (const record of delta) if (!baselineKeys.has(key(record))) merged.push(record);
	return merged;
}

function uniqueRecords<T>(
	records: ReadonlyArray<T>,
	key: (record: T) => string,
	source: string,
): Map<string, T> {
	const result = new Map<string, T>();
	for (const record of records) {
		const recordKey = key(record);
		if (result.has(recordKey)) {
			throw new Error(`MARKLESS_RESUME_RECORD_DELTA_DUPLICATE_KEY: ${source} ${recordKey}.`);
		}
		result.set(recordKey, record);
	}
	return result;
}

function mergeOptionalRecords<
	T extends object,
	K extends {
		[P in keyof T]-?: T[P] extends ReadonlyArray<unknown> | undefined ? P : never;
	}[keyof T],
>(
	baseline: T,
	delta: T,
	property: K,
	key: (record: NonNullable<T[K]> extends ReadonlyArray<infer R> ? R : never) => string,
): Partial<Pick<T, K>> {
	if (!(property in delta)) return {};
	return {
		[property]: mergeRecords(
			(baseline[property] ?? []) as ReadonlyArray<never>,
			(delta[property] ?? []) as ReadonlyArray<never>,
			key,
		),
	} as Partial<Pick<T, K>>;
}

function mergeAsyncRunners(
	baseline: ProtocolViewPayload,
	delta: ProtocolViewPayload,
): Pick<ProtocolViewPayload, 'asyncRunners'> | Record<never, never> {
	if (!('asyncRunners' in delta)) return {};
	return { asyncRunners: { ...baseline.asyncRunners, ...delta.asyncRunners } };
}

function assertMatchingVersion(baseline: number, delta: number, payload: string): void {
	if (baseline !== delta)
		throw new Error(
			`MARKLESS_RESUME_RECORD_DELTA_VERSION_MISMATCH: ${payload} ${baseline} !== ${delta}.`,
		);
}

// The storage key grammar, alone in its own module on purpose.
//
// The production payload decoder (protocol-client) must validate storage keys,
// so whatever module it imports this from is in every resuming page's eager
// chunk. The rest of the storage surface — the slot symbol, the slot-entry key
// derivation, the no-flash attribute name — is client-storage-only and is
// demand-loaded with the storage plane. Keeping them in one module put all of
// it in the eager chunk, because a lazy chunk importing from an eager module
// pins that module's exports there.
//
// A storage key is either an author's verbatim explicit key or a derived
// markless:<identifier>. Permissive but structurally safe: letters, digits, and
// $ _ : . - only (no whitespace, quotes, brackets, or control characters). The
// colon admits the markless: namespace; the resume decoder uses this to reject
// malformed payloads.
const STORAGE_KEY_PATTERN = /^[A-Za-z0-9$_:.-]+$/;

export function isValidStorageKey(value: string): boolean {
	return STORAGE_KEY_PATTERN.test(value);
}

import type { ProtocolStatePayload } from './protocol.ts';
import { STORAGE_PROTOCOL_VERSION } from './protocol-constants.ts';
import { isValidStorageKey } from './storage-key.ts';

export function validateStorageRecords(
	payload: ProtocolStatePayload,
	invalid: (type: 'markless/state', message: string) => Error,
): void {
	if (payload.version !== STORAGE_PROTOCOL_VERSION) return;
	if (!Array.isArray(payload.storage))
		throw invalid('markless/state', 'Invalid markless/state storage: expected array.');
	for (const entry of payload.storage) {
		if (
			typeof entry !== 'object' ||
			entry === null ||
			typeof entry.key !== 'string' ||
			!isValidStorageKey(entry.key) ||
			!payload.cells.some((cell) => cell.graphNodeId === entry.graphNodeId)
		)
			throw invalid(
				'markless/state',
				'Invalid markless/state storage: invalid storage record.',
			);
	}
}

export { isValidStorageKey } from './storage-key.ts';

export const STORAGE_SLOT_SYMBOL_KEY = 'tsrx.storage/1';

// The no-flash <html> attribute name for a driver key. Derived keys contain a
// colon (markless:theme) which is not a clean attribute name, so any character
// outside [A-Za-z0-9-] collapses to a hyphen: markless:theme -> data-markless-theme,
// theme -> data-theme. Used identically by the seed script and the storage plane
// so both write the same attribute.
export function storageAttributeName(driverKey: string): string {
	return `data-${driverKey.replace(/[^A-Za-z0-9-]+/g, '-')}`;
}

export type StorageSeedMetadata = {
	readonly slotKey: string;
	readonly driverKey: string;
	readonly fallback: string;
};

export function storageSlotEntryKey(moduleId: string, key: string): string {
	return `${moduleId}#${key}`;
}

export function storageSlotEntryKeyFromGraphNodeId(graphNodeId: string): string {
	return graphNodeId.startsWith('storage:') ? graphNodeId.slice('storage:'.length) : graphNodeId;
}

export function createStorageSeedMetadata(
	moduleId: string,
	driverKey: string,
	fallback: string,
): StorageSeedMetadata {
	return {
		slotKey: storageSlotEntryKey(moduleId, driverKey),
		driverKey,
		fallback,
	};
}

// The seed's slotKey MUST anchor to the same graphNodeId the wake-time override
// (payload-graph-construct) derives its lookup key from — otherwise a warm slot
// is written under one key and read under another, and the component silently
// falls back. Derive it from the graphNodeId so they match by construction.
export function createStorageSeedMetadataFromGraphNodeId(
	graphNodeId: string,
	driverKey: string,
	fallback: string,
): StorageSeedMetadata {
	return {
		slotKey: storageSlotEntryKeyFromGraphNodeId(graphNodeId),
		driverKey,
		fallback,
	};
}

import type { SerializedGraphPayload } from './value.ts';

export const GRAPH_VALUE_PROTOCOL_VERSION = 1;

// Browser-side linked render data creates only a pending/null snapshot before
// the demanded graph exists. Keep that protocol value here so the evaluator
// does not pull the general graph serializer into every emitted client build.
export const SERIALIZED_NULL_GRAPH_PAYLOAD: SerializedGraphPayload = {
	version: GRAPH_VALUE_PROTOCOL_VERSION,
	root: null,
	records: [],
};

import type { SerializedGraphPayload, SerializedRecord, SerializedSlot } from './value.ts';

export type { SerializedGraphPayload, SerializedRecord, SerializedSlot } from './value.ts';

export type ValueDecodeExtensions = {
	readonly recordShell: (
		record: SerializedRecord,
		shells: ReadonlyMap<number, unknown>,
	) => unknown;
	readonly slot: (slot: SerializedSlot) => unknown;
};

export async function deserializeGraphValueForClient(
	payload: SerializedGraphPayload,
): Promise<unknown> {
	const extensions = payloadNeedsExtendedDecoders(payload)
		? (await import('./value-decode-extensions.ts')).valueDecodeExtensions
		: undefined;
	return deserializeGraphValueWithExtensions(payload, extensions);
}

function deserializeGraphValueWithExtensions(
	payload: SerializedGraphPayload,
	extensions?: ValueDecodeExtensions,
): unknown {
	const shells = new Map<number, unknown>();

	for (const record of payload.records) {
		if (record.type === 'object') shells.set(record.id, {});
		if (record.type === 'array') shells.set(record.id, []);
		if (record.type === 'map') shells.set(record.id, new Map());
		if (record.type === 'set') shells.set(record.id, new Set());
		if (record.type === 'date') shells.set(record.id, new Date(record.value));
		const shell = extensions?.recordShell(record, shells);
		if (shell !== undefined) shells.set(record.id, shell);
	}

	for (const record of payload.records) {
		if (record.type === 'typed-array' || record.type === 'data-view') {
			const shell = extensions?.recordShell(record, shells);
			if (shell !== undefined) shells.set(record.id, shell);
		}
	}

	for (const record of payload.records) {
		const shell = shells.get(record.id);
		if (record.type === 'object') {
			const object = shell as Record<string, unknown>;
			for (const [key, slot] of record.fields) {
				object[key] = decodeSlot(slot, shells, extensions);
			}
		}
		if (record.type === 'array') {
			const array = shell as unknown[];
			for (const item of record.items) array.push(decodeSlot(item, shells, extensions));
		}
		if (record.type === 'map') {
			const map = shell as Map<unknown, unknown>;
			for (const [key, value] of record.entries) {
				map.set(decodeSlot(key, shells, extensions), decodeSlot(value, shells, extensions));
			}
		}
		if (record.type === 'set') {
			const set = shell as Set<unknown>;
			for (const value of record.values) set.add(decodeSlot(value, shells, extensions));
		}
	}

	return decodeSlot(payload.root, shells, extensions);
}

function decodeSlot(
	slot: SerializedSlot,
	shells: ReadonlyMap<number, unknown>,
	extensions?: ValueDecodeExtensions,
): unknown {
	if (
		slot === null ||
		typeof slot === 'string' ||
		typeof slot === 'number' ||
		typeof slot === 'boolean'
	)
		return slot;
	if ('$ref' in slot) return shells.get(slot.$ref);
	if (slot.$type === 'undefined') return undefined;
	if (slot.$type === 'bigint') return BigInt(slot.value);
	if (slot.$type === 'date') return new Date(slot.value);
	return extensions?.slot(slot);
}

function payloadNeedsExtendedDecoders(payload: SerializedGraphPayload): boolean {
	if (slotNeedsExtendedDecoder(payload.root)) return true;
	return payload.records.some((record) => {
		if (
			record.type === 'regexp' ||
			record.type === 'url' ||
			record.type === 'array-buffer' ||
			record.type === 'typed-array' ||
			record.type === 'data-view'
		)
			return true;
		if (record.type === 'object') {
			return record.fields.some(([, slot]) => slotNeedsExtendedDecoder(slot));
		}
		if (record.type === 'array') return record.items.some(slotNeedsExtendedDecoder);
		if (record.type === 'map') {
			return record.entries.some(
				([key, value]) => slotNeedsExtendedDecoder(key) || slotNeedsExtendedDecoder(value),
			);
		}
		if (record.type === 'set') return record.values.some(slotNeedsExtendedDecoder);
		return false;
	});
}

function slotNeedsExtendedDecoder(slot: SerializedSlot): boolean {
	return (
		typeof slot === 'object' &&
		slot !== null &&
		'$type' in slot &&
		(slot.$type === 'regexp' || slot.$type === 'url')
	);
}

import type { ValueDecodeExtensions } from './value-decode-client.ts';
import type { SerializedRecord, SerializedSlot } from './value.ts';

type TypedArrayConstructor = new (
	buffer: ArrayBuffer,
	byteOffset: number,
	length: number,
) => unknown;

export const valueDecodeExtensions: ValueDecodeExtensions = {
	recordShell(record, shells) {
		if (record.type === 'regexp') return new RegExp(record.source, record.flags);
		if (record.type === 'url') return new URL(record.value);
		if (record.type === 'array-buffer') return new Uint8Array(record.bytes).buffer;
		if (record.type === 'typed-array') return createTypedArray(record, shells);
		if (record.type === 'data-view') return createDataView(record, shells);
	},
	slot(slot) {
		if (typeof slot !== 'object' || slot === null || !('$type' in slot)) return undefined;
		if (slot.$type === 'regexp') return new RegExp(slot.source, slot.flags);
		if (slot.$type === 'url') return new URL(slot.value);
	},
};

function createTypedArray(
	record: Extract<SerializedRecord, { readonly type: 'typed-array' }>,
	shells: ReadonlyMap<number, unknown>,
): unknown {
	const buffer = decodeSlot(record.buffer, shells);
	if (!(buffer instanceof ArrayBuffer)) return undefined;
	const constructor = (globalThis as Record<string, unknown>)[record.arrayType];
	return typeof constructor === 'function'
		? new (constructor as TypedArrayConstructor)(buffer, record.byteOffset, record.length)
		: undefined;
}

function createDataView(
	record: Extract<SerializedRecord, { readonly type: 'data-view' }>,
	shells: ReadonlyMap<number, unknown>,
): unknown {
	const buffer = decodeSlot(record.buffer, shells);
	return buffer instanceof ArrayBuffer
		? new DataView(buffer, record.byteOffset, record.byteLength)
		: undefined;
}

function decodeSlot(slot: SerializedSlot, shells: ReadonlyMap<number, unknown>): unknown {
	if (typeof slot !== 'object' || slot === null) return slot;
	if ('$ref' in slot) return shells.get(slot.$ref);
	if (slot.$type === 'regexp') return new RegExp(slot.source, slot.flags);
	if (slot.$type === 'url') return new URL(slot.value);
}

import type { SerializedGraphPayload, SerializedRecord, SerializedSlot } from './value.ts';

export type { SerializedGraphPayload, SerializedRecord, SerializedSlot } from './value.ts';

export function deserializeGraphValue(payload: SerializedGraphPayload): unknown {
	const shells = new Map<number, unknown>();

	for (const record of payload.records) {
		if (record.type === 'object') shells.set(record.id, {});
		if (record.type === 'array') shells.set(record.id, []);
		if (record.type === 'map') shells.set(record.id, new Map());
		if (record.type === 'set') shells.set(record.id, new Set());
		if (record.type === 'date') shells.set(record.id, new Date(record.value));
		if (record.type === 'regexp')
			shells.set(record.id, new RegExp(record.source, record.flags));
		if (record.type === 'url') shells.set(record.id, new URL(record.value));
		if (record.type === 'array-buffer')
			shells.set(record.id, new Uint8Array(record.bytes).buffer);
	}

	for (const record of payload.records) {
		if (record.type === 'typed-array') {
			shells.set(record.id, createTypedArray(record, shells));
		}
		if (record.type === 'data-view') {
			shells.set(record.id, createDataView(record, shells));
		}
	}

	for (const record of payload.records) {
		const shell = shells.get(record.id);

		if (record.type === 'object') {
			const object = shell as Record<string, unknown>;
			for (const [key, slot] of record.fields) {
				object[key] = decodeSlot(slot, shells);
			}
		}

		if (record.type === 'array') {
			const array = shell as unknown[];
			for (const item of record.items) {
				array.push(decodeSlot(item, shells));
			}
		}

		if (record.type === 'map') {
			const map = shell as Map<unknown, unknown>;
			for (const [key, value] of record.entries) {
				map.set(decodeSlot(key, shells), decodeSlot(value, shells));
			}
		}

		if (record.type === 'set') {
			const set = shell as Set<unknown>;
			for (const value of record.values) {
				set.add(decodeSlot(value, shells));
			}
		}
	}

	return decodeSlot(payload.root, shells);
}

function decodeSlot(slot: SerializedSlot, shells: ReadonlyMap<number, unknown>): unknown {
	if (
		slot === null ||
		typeof slot === 'string' ||
		typeof slot === 'number' ||
		typeof slot === 'boolean'
	) {
		return slot;
	}

	if ('$ref' in slot) return shells.get(slot.$ref);
	if (slot.$type === 'undefined') return undefined;
	if (slot.$type === 'bigint') return BigInt(slot.value);
	if (slot.$type === 'date') return new Date(slot.value);
	if (slot.$type === 'regexp') return new RegExp(slot.source, slot.flags);
	if (slot.$type === 'url') return new URL(slot.value);

	return undefined;
}

type TypedArrayConstructor = new (
	buffer: ArrayBuffer,
	byteOffset: number,
	length: number,
) => unknown;

function createTypedArray(
	record: Extract<SerializedRecord, { readonly type: 'typed-array' }>,
	shells: ReadonlyMap<number, unknown>,
): unknown {
	const buffer = decodeSlot(record.buffer, shells);
	if (!(buffer instanceof ArrayBuffer)) return undefined;
	const constructor = (globalThis as Record<string, unknown>)[record.arrayType];
	return typeof constructor === 'function'
		? new (constructor as TypedArrayConstructor)(buffer, record.byteOffset, record.length)
		: undefined;
}

function createDataView(
	record: Extract<SerializedRecord, { readonly type: 'data-view' }>,
	shells: ReadonlyMap<number, unknown>,
): unknown {
	const buffer = decodeSlot(record.buffer, shells);
	if (!(buffer instanceof ArrayBuffer)) return undefined;

	return new DataView(buffer, record.byteOffset, record.byteLength);
}

import { GRAPH_VALUE_PROTOCOL_VERSION } from './value-constants.ts';

export type SerializedPrimitive =
	| null
	| string
	| number
	| boolean
	| { readonly $type: 'undefined' }
	| { readonly $type: 'bigint'; readonly value: string };

export type SerializedSlot =
	| SerializedPrimitive
	| { readonly $ref: number }
	| { readonly $type: 'date'; readonly value: string }
	| { readonly $type: 'regexp'; readonly source: string; readonly flags: string }
	| { readonly $type: 'url'; readonly value: string };

export type SerializedRecord =
	| {
			readonly id: number;
			readonly type: 'object';
			readonly fields: ReadonlyArray<readonly [string, SerializedSlot]>;
	  }
	| {
			readonly id: number;
			readonly type: 'array';
			readonly items: ReadonlyArray<SerializedSlot>;
	  }
	| {
			readonly id: number;
			readonly type: 'map';
			readonly entries: ReadonlyArray<readonly [SerializedSlot, SerializedSlot]>;
	  }
	| {
			readonly id: number;
			readonly type: 'set';
			readonly values: ReadonlyArray<SerializedSlot>;
	  }
	| {
			readonly id: number;
			readonly type: 'date';
			readonly value: string;
	  }
	| {
			readonly id: number;
			readonly type: 'regexp';
			readonly source: string;
			readonly flags: string;
	  }
	| {
			readonly id: number;
			readonly type: 'url';
			readonly value: string;
	  }
	| {
			readonly id: number;
			readonly type: 'array-buffer';
			readonly bytes: ReadonlyArray<number>;
	  }
	| {
			readonly id: number;
			readonly type: 'typed-array';
			readonly arrayType: TypedArrayName;
			readonly buffer: SerializedSlot;
			readonly byteOffset: number;
			readonly length: number;
	  }
	| {
			readonly id: number;
			readonly type: 'data-view';
			readonly buffer: SerializedSlot;
			readonly byteOffset: number;
			readonly byteLength: number;
	  };

export type TypedArrayName =
	| 'Int8Array'
	| 'Uint8Array'
	| 'Uint8ClampedArray'
	| 'Int16Array'
	| 'Uint16Array'
	| 'Int32Array'
	| 'Uint32Array'
	| 'Float32Array'
	| 'Float64Array'
	| 'BigInt64Array'
	| 'BigUint64Array';

export type SerializedGraphPayload = {
	readonly version: typeof GRAPH_VALUE_PROTOCOL_VERSION;
	readonly root: SerializedSlot;
	readonly records: ReadonlyArray<SerializedRecord>;
};

export type SerializationDiagnostic = {
	readonly code: 'MARKLESS_SERIALIZE_UNSUPPORTED_VALUE';
	readonly severity: 'error';
	readonly phase: 'serialization';
	readonly title: 'Cannot serialize graph state value';
	readonly path: ReadonlyArray<string>;
	readonly statePath: string;
	readonly valueKind: string;
	readonly message: string;
	readonly why: string;
	readonly suggestions: ReadonlyArray<{ readonly message: string }>;
	readonly docsUrl: string;
};

export type SerializationResult =
	| {
			readonly ok: true;
			readonly payload: SerializedGraphPayload;
			readonly diagnostics: readonly [];
	  }
	| {
			readonly ok: false;
			readonly diagnostics: ReadonlyArray<SerializationDiagnostic>;
	  };

export { deserializeGraphValue } from './value-decode.ts';

export function serializeGraphValue(value: unknown): SerializationResult {
	const diagnostics: SerializationDiagnostic[] = [];
	const seen = new WeakMap<object, number>();
	const records: SerializedRecord[] = [];

	const root = encodeSlot(value, [], seen, records, diagnostics);
	if (root === undefined || diagnostics.length > 0) {
		return {
			ok: false,
			diagnostics,
		};
	}

	return {
		ok: true,
		payload: {
			version: GRAPH_VALUE_PROTOCOL_VERSION,
			root,
			records,
		},
		diagnostics: [],
	};
}

function encodeSlot(
	value: unknown,
	path: ReadonlyArray<string>,
	seen: WeakMap<object, number>,
	records: SerializedRecord[],
	diagnostics: SerializationDiagnostic[],
): SerializedSlot | undefined {
	if (value === null) return null;
	if (typeof value === 'string' || typeof value === 'number' || typeof value === 'boolean') {
		return value;
	}
	if (typeof value === 'undefined') return { $type: 'undefined' };
	if (typeof value === 'bigint') return { $type: 'bigint', value: String(value) };

	if (typeof value === 'function' || typeof value === 'symbol') {
		diagnostics.push(unsupportedDiagnostic(value, path));
		return undefined;
	}

	if (!isObject(value)) {
		diagnostics.push(unsupportedDiagnostic(value, path));
		return undefined;
	}

	if (value instanceof Date) {
		const existingId = seen.get(value);
		if (existingId !== undefined) return { $ref: existingId };

		const id = records.length;
		seen.set(value, id);
		records.push({ id, type: 'date', value: value.toISOString() });
		return { $ref: id };
	}
	if (value instanceof RegExp) {
		const existingId = seen.get(value);
		if (existingId !== undefined) return { $ref: existingId };

		const id = records.length;
		seen.set(value, id);
		records.push({ id, type: 'regexp', source: value.source, flags: value.flags });
		return { $ref: id };
	}
	if (value instanceof URL) {
		const existingId = seen.get(value);
		if (existingId !== undefined) return { $ref: existingId };

		const id = records.length;
		seen.set(value, id);
		records.push({ id, type: 'url', value: value.toString() });
		return { $ref: id };
	}

	if (value instanceof ArrayBuffer) {
		const existingId = seen.get(value);
		if (existingId !== undefined) return { $ref: existingId };

		const id = records.length;
		seen.set(value, id);
		records.push({
			id,
			type: 'array-buffer',
			bytes: [...new Uint8Array(value)],
		});
		return { $ref: id };
	}

	const arrayType = typedArrayName(value);
	if (arrayType) {
		const existingId = seen.get(value);
		if (existingId !== undefined) return { $ref: existingId };

		const id = records.length;
		seen.set(value, id);
		records.push({
			id,
			type: 'typed-array',
			arrayType,
			buffer: encodeArrayBufferViewBuffer(value, path, seen, records, diagnostics),
			byteOffset: typedArrayByteOffset(value),
			length: typedArrayLength(value),
		});
		return { $ref: id };
	}
	if (value instanceof DataView) {
		const existingId = seen.get(value);
		if (existingId !== undefined) return { $ref: existingId };

		const id = records.length;
		seen.set(value, id);
		records.push({
			id,
			type: 'data-view',
			buffer: encodeArrayBufferViewBuffer(value, path, seen, records, diagnostics),
			byteOffset: value.byteOffset,
			byteLength: value.byteLength,
		});
		return { $ref: id };
	}

	const existingId = seen.get(value);
	if (existingId !== undefined) return { $ref: existingId };

	const id = records.length;
	seen.set(value, id);

	if (Array.isArray(value)) {
		const record: Extract<SerializedRecord, { readonly type: 'array' }> = {
			id,
			type: 'array',
			items: [],
		};
		records.push(record);
		(record.items as SerializedSlot[]).push(
			...value
				.map((item, index) =>
					encodeSlot(item, [...path, String(index)], seen, records, diagnostics),
				)
				.filter(isSerializedSlot),
		);
		return { $ref: id };
	}

	if (value instanceof Map) {
		const record: Extract<SerializedRecord, { readonly type: 'map' }> = {
			id,
			type: 'map',
			entries: [],
		};
		records.push(record);
		let index = 0;
		for (const [key, item] of value) {
			const keySlot = encodeSlot(
				key,
				[...path, `mapKey:${index}`],
				seen,
				records,
				diagnostics,
			);
			const valueSlot = encodeSlot(
				item,
				[...path, `mapValue:${index}`],
				seen,
				records,
				diagnostics,
			);
			if (keySlot !== undefined && valueSlot !== undefined) {
				(record.entries as Array<readonly [SerializedSlot, SerializedSlot]>).push([
					keySlot,
					valueSlot,
				]);
			}
			index++;
		}
		return { $ref: id };
	}

	if (value instanceof Set) {
		const record: Extract<SerializedRecord, { readonly type: 'set' }> = {
			id,
			type: 'set',
			values: [],
		};
		records.push(record);
		let index = 0;
		for (const item of value) {
			const slot = encodeSlot(item, [...path, `set:${index}`], seen, records, diagnostics);
			if (slot !== undefined) (record.values as SerializedSlot[]).push(slot);
			index++;
		}
		return { $ref: id };
	}

	if (!isPlainObject(value)) {
		diagnostics.push(unsupportedDiagnostic(value, path));
		return undefined;
	}

	const record: Extract<SerializedRecord, { readonly type: 'object' }> = {
		id,
		type: 'object',
		fields: [],
	};
	records.push(record);

	for (const [key, item] of Object.entries(value)) {
		const slot = encodeSlot(item, [...path, key], seen, records, diagnostics);
		if (slot !== undefined) {
			(record.fields as Array<readonly [string, SerializedSlot]>).push([key, slot]);
		}
	}

	return { $ref: id };
}

function typedArrayName(value: object): TypedArrayName | null {
	if (value instanceof Int8Array) return 'Int8Array';
	if (value instanceof Uint8Array) return 'Uint8Array';
	if (value instanceof Uint8ClampedArray) return 'Uint8ClampedArray';
	if (value instanceof Int16Array) return 'Int16Array';
	if (value instanceof Uint16Array) return 'Uint16Array';
	if (value instanceof Int32Array) return 'Int32Array';
	if (value instanceof Uint32Array) return 'Uint32Array';
	if (value instanceof Float32Array) return 'Float32Array';
	if (value instanceof Float64Array) return 'Float64Array';
	if (typeof BigInt64Array !== 'undefined' && value instanceof BigInt64Array) {
		return 'BigInt64Array';
	}
	if (typeof BigUint64Array !== 'undefined' && value instanceof BigUint64Array) {
		return 'BigUint64Array';
	}

	return null;
}

function encodeArrayBufferViewBuffer(
	value: object,
	path: ReadonlyArray<string>,
	seen: WeakMap<object, number>,
	records: SerializedRecord[],
	diagnostics: SerializationDiagnostic[],
): SerializedSlot {
	const buffer = (value as ArrayBufferView).buffer;
	if (!(buffer instanceof ArrayBuffer)) {
		diagnostics.push(unsupportedDiagnostic(buffer, [...path, 'buffer']));
		return null;
	}

	return encodeSlot(buffer, [...path, 'buffer'], seen, records, diagnostics) ?? null;
}

function typedArrayByteOffset(value: object): number {
	return (value as ArrayBufferView).byteOffset;
}

function typedArrayLength(value: object): number {
	return (value as ArrayBufferView & { readonly length: number }).length;
}

function unsupportedDiagnostic(
	value: unknown,
	path: ReadonlyArray<string>,
): SerializationDiagnostic {
	const valueKind = describeUnsupportedValue(value);
	const formattedPath = formatPath(path);
	const isClassOrHost = isObject(value) && !isPlainObject(value);

	return {
		code: 'MARKLESS_SERIALIZE_UNSUPPORTED_VALUE',
		severity: 'error',
		phase: 'serialization',
		title: 'Cannot serialize graph state value',
		path,
		statePath: formattedPath,
		valueKind,
		message: isClassOrHost
			? `Cannot serialize value at ${formattedPath} because ${valueKind} is a live host/class resource that is not durable graph state and would resume as an empty/plain object.`
			: `Cannot serialize value at ${formattedPath} because ${valueKind} values are not durable graph state.`,
		why: isClassOrHost
			? 'Serialization is for durable graph state. Host and runtime resources cannot be reconstructed from a payload during resume.'
			: 'Serialization is for durable graph state. Functions and host/runtime resources cannot be restored during resume.',
		suggestions: [
			{
				message: isClassOrHost
					? 'Keep live resources in attach={...} behaviors and store serializable connection data such as URLs and status flags in state.'
					: 'Move runtime resources into attach={...}, make the value serializable state, or derive it with computed().',
			},
		],
		docsUrl: 'https://markless.dev/errors/MARKLESS_SERIALIZE_UNSUPPORTED_VALUE',
	};
}

function formatPath(path: ReadonlyArray<string>): string {
	return path.length === 0 ? '<root>' : path.join('.');
}

function isObject(value: unknown): value is object {
	return typeof value === 'object' && value !== null;
}

function isPlainObject(value: object): boolean {
	const prototype = Object.getPrototypeOf(value);
	return prototype === Object.prototype || prototype === null;
}

function describeUnsupportedValue(value: unknown): string {
	if (isObject(value)) return value.constructor?.name ?? 'object';
	return typeof value;
}

function isSerializedSlot(value: SerializedSlot | undefined): value is SerializedSlot {
	return value !== undefined;
}

